-- ==== src/00_header.lua ====
-- Holo: watch parties for Worms Ultimate Mayhem. Client-only. This file is generated by tools/build_lua.py from
-- src/*.lua (name order); edit the fragments, not this file. Every fragment is one do ... end block that fills one
-- of the namespace tables below, so the chunk keeps far fewer than 200 top-level locals.
local U, CFG, NET, PARTY, QUEUE, SPOT, MUSIC, LAYOUT, SKIN, W, PUI, SETUP, MUI, MAIN = {}, {}, {}, {}, {}, {}, {}, {},
  {}, {}, {}, {}, {}, {}
local VERSION = "1.1.0"

if not (wum and wum.media and wum.peer and wum.input and wum.draw and wum.draw.hudNine) then
  wum.log.warn("Holo needs Melange 0.12.0 or later (wum.media, wum.peer, wum.input and wum.draw.hudNine); not started")
  return
end

-- Tests read the namespaces through this hook; the real game never defines it.
if wum._holoTest then
  wum._holoTest.ns = {U = U, CFG = CFG, NET = NET, PARTY = PARTY, QUEUE = QUEUE, LAYOUT = LAYOUT, SKIN = SKIN,
    W = W, PUI = PUI, SETUP = SETUP, MAIN = MAIN, SPOT = SPOT, MUSIC = MUSIC, MUI = MUI}
end

do
  -- Log with a level: U.log("info", ...). Unknown levels fall back to info.
  function U.log(level, ...)
    local f = wum.log[level] or wum.log.info
    f("[holo]", ...)
  end

  -- In-file bus. U.emit runs the listeners of a name synchronously, in subscription order; a listener that raises
  -- is logged and skipped, it never stops the others.
  local listeners = {}

  function U.on(name, fn)
    local l = listeners[name]
    if not l then
      l = {}
      listeners[name] = l
    end
    l[#l + 1] = fn
    return fn
  end

  function U.off(name, fn)
    local l = listeners[name]
    if not l then return false end
    for i = 1, #l do
      if l[i] == fn then
        table.remove(l, i)
        return true
      end
    end
    return false
  end

  function U.emit(name, ...)
    local l = listeners[name]
    if not l then return end
    local copy = {table.unpack(l)}
    for i = 1, #copy do
      local ok, err = pcall(copy[i], ...)
      if not ok then U.log("error", "listener", name, err) end
    end
  end

  -- U.guard(name, fn) -> a wrapper that runs fn under pcall. Three errors in a row stop that piece (it then does
  -- nothing and returns nil) and the third is logged once; a success resets the count. Used for every per-frame or
  -- event piece, the Kanly pattern.
  local STRIKES = 3
  function U.guard(name, fn)
    local strikes, dead = 0, false
    return function(...)
      if dead then return end
      local r = table.pack(pcall(fn, ...))
      if r[1] then
        strikes = 0
        return table.unpack(r, 2, r.n)
      end
      strikes = strikes + 1
      U.log("error", name, r[2])
      if strikes >= STRIKES then
        dead = true
        U.log("error", name, "stopped after " .. STRIKES .. " errors")
      end
    end
  end
end

-- ==== src/10_util.lua ====
-- util (P2): small helpers every fragment uses, and the per-machine preferences kept in wum.storage.
do
  function U.clamp(x, lo, hi)
    if x < lo then return lo end
    if x > hi then return hi end
    return x
  end

  function U.lerp(a, b, t) return a + (b - a) * t end

  function U.easeOutCubic(t)
    t = U.clamp(t, 0, 1) - 1
    return t * t * t + 1
  end

  -- A finite number, or nil (NaN and the infinities are refused). Used on every number that came off the wire.
  function U.num(v)
    if type(v) ~= "number" or v ~= v or v == math.huge or v == -math.huge then return nil end
    return v
  end

  -- "12:34" below an hour, "1:02:11" from an hour on; nil, NaN and negatives read as 0.
  function U.fmtTime(sec)
    sec = math.floor(U.num(sec) or 0)
    if sec < 0 then sec = 0 end
    local h, m, s = sec // 3600, (sec // 60) % 60, sec % 60
    if h > 0 then return string.format("%d:%02d:%02d", h, m, s) end
    return string.format("%d:%02d", m, s)
  end

  -- Turns control characters into spaces, strips the outer spaces and keeps at most n characters. UTF-8 aware:
  -- the bytes of a broken sequence are dropped, never cut in half. Anything but a string gives "".
  function U.trim(s, n)
    if type(s) ~= "string" then return "" end
    s = s:gsub("%c", " ")
    if not utf8.len(s) then
      local out, i, size = {}, 1, #s
      while i <= size do
        local c, len = s:byte(i), 0
        if c < 0x80 then len = 1
        elseif c >= 0xC2 and c <= 0xDF then len = 2
        elseif c >= 0xE0 and c <= 0xEF then len = 3
        elseif c >= 0xF0 and c <= 0xF4 then len = 4 end
        local ch = len > 0 and s:sub(i, i + len - 1) or ""
        if len > 0 and #ch == len and utf8.len(ch) == 1 then
          out[#out + 1] = ch
          i = i + len
        else
          i = i + 1
        end
      end
      s = table.concat(out)
    end
    s = s:match("^%s*(.-)%s*$")
    if n and utf8.len(s) > n then s = s:sub(1, utf8.offset(s, n + 1) - 1) end
    return s
  end

  -- The peer bus clock in ms; every Holo timestamp uses it, so host and peer times compare through ch:clock().
  function U.now() return wum.peer.now() end

  function U.copy(v)
    if type(v) ~= "table" then return v end
    local t = {}
    for k, x in pairs(v) do t[k] = U.copy(x) end
    return t
  end

  -- Preferences: one storage key holding a table, read once and written at most once a second after the last change
  -- (wum.storage then saves the file within 2 s).
  local PREFS_KEY = "prefs"
  local prefs, dirtyAt

  local function loadPrefs()
    if prefs then return prefs end
    local ok, v = pcall(wum.storage.get, PREFS_KEY)
    prefs = (ok and type(v) == "table") and v or {}
    return prefs
  end

  function U.pref(key, default)
    local v = loadPrefs()[key]
    if v == nil then return default end
    return v
  end

  function U.setPref(key, value)
    local p = loadPrefs()
    if type(value) ~= "table" and p[key] == value then return end
    p[key] = U.copy(value)
    dirtyAt = U.now()
  end

  function U.flushPrefs()
    if not dirtyAt then return end
    dirtyAt = nil
    local ok, err = pcall(wum.storage.set, PREFS_KEY, prefs)
    if not ok then U.log("warn", "could not save the preferences:", err) end
  end

  wum.timers.every(0.25, U.guard("prefs", function()
    if dirtyAt and U.now() - dirtyAt >= 1000 then U.flushPrefs() end
  end))
end

-- ==== src/20_config.lua ====
-- config (P2): the spice.json settings, polled every 0.5 s, and the four hotkeys they name.
do
  -- The settings of spice.json with their defaults and limits, so a hand-edited Melange.ini with a value out of range
  -- or an option that no longer exists reads as the default instead of breaking a fragment.
  local DEFS = {
    volume = {"int", 70, 0, 100},
    quality = {"enum", "720", {"360", "480", "720", "1080"}},
    hiddenMutes = {"bool", true},
    autoHideAim = {"bool", true},
    panelSide = {"enum", "right", {"right", "left"}},
    bigOnOthers = {"bool", true},
    musicOff = {"bool", true},
    whoAdds = {"enum", "anyone", {"anyone", "host"}},
    musicDuringVideo = {"enum", "pause", {"pause", "play"}},
    musicFollow = {"bool", true},
    musicChip = {"bool", true},
    uiScale = {"int", 100, 80, 130},
    keySetup = {"enum", "F6", {"F6", "Ctrl+Shift+W", "Alt+W"}},
    keyPointer = {"enum", "F7", {"F7", "Ctrl+Shift+M", "Alt+M"}},
    keyHide = {"enum", "F9", {"F9", "Ctrl+Shift+H", "Alt+H"}},
    keyPlay = {"enum", "Ctrl+Shift+P", {"Ctrl+Shift+P", "Ctrl+F9"}},
  }
  CFG.DEFS = DEFS
  -- hotkey bus name -> setting
  local HOTKEYS = {setup = "keySetup", pointer = "keyPointer", hide = "keyHide", play = "keyPlay"}
  CFG.HOTKEYS = HOTKEYS
  local KEYS, NAMES = {}, {"setup", "pointer", "hide", "play"}
  for k in pairs(DEFS) do KEYS[#KEYS + 1] = k end
  table.sort(KEYS)

  local function sanitize(key, v)
    local d = DEFS[key]
    if not d then return v end
    if d[1] == "int" then
      v = U.num(v)
      if not v then return d[2] end
      return math.floor(U.clamp(v, d[3], d[4]))
    elseif d[1] == "bool" then
      if type(v) ~= "boolean" then return d[2] end
      return v
    end
    for _, o in ipairs(d[3]) do
      if o == v then return v end
    end
    return d[2]
  end
  CFG.sanitize = sanitize

  local values = {}

  local function read(key)
    local ok, v = pcall(wum.config.get, key)
    if not ok then v = nil end
    return sanitize(key, v)
  end

  function CFG.get(key)
    local v = values[key]
    if v == nil then
      v = read(key)
      values[key] = v
    end
    return v
  end

  -- Hotkeys: the chosen key, else the setting's default, else any other option (a key another mod took raises).
  local handles, wanted, active = {}, {}, {}

  local function register(name)
    local key = CFG.get(HOTKEYS[name])
    if wanted[name] == key then return end
    wanted[name] = key
    if handles[name] then pcall(wum.ui.remove, handles[name]) end
    handles[name], active[name] = nil, nil
    local d = DEFS[HOTKEYS[name]]
    local tries = {key, d[2]}
    for _, o in ipairs(d[3]) do tries[#tries + 1] = o end
    local fire = U.guard("hotkey." .. name, function() U.emit("hotkey", name) end)
    for _, k in ipairs(tries) do
      local ok, h = pcall(wum.ui.hotkey, k, fire)
      if ok then
        handles[name], active[name] = h, k
        if k ~= key then U.log("warn", "hotkey", key, "is not available; using", k) end
        return
      end
    end
    U.log("warn", "no hotkey could be registered for", name)
  end

  -- The key actually registered for a hotkey name (it can differ from the setting after a fallback), or nil.
  function CFG.hotkeyKey(name) return active[name] end

  function CFG.poll()
    for _, key in ipairs(KEYS) do
      local v = read(key)
      if values[key] ~= v then
        local had = values[key] ~= nil
        values[key] = v
        if had then U.emit("cfg.changed", key, v) end
      end
    end
    for _, name in ipairs(NAMES) do register(name) end
  end

  CFG.poll()
  wum.timers.every(0.5, U.guard("config", CFG.poll))
end

-- ==== src/30_net.lua ====
-- net (P2): the lobby as Holo sees it, the wum.peer channel (version 1), presence and a paced outbox.
-- Bus events: "lobby.changed" (members, owner, phase or someone's presence changed), "net.enter", "net.leave",
-- "net.owner" (owner, isHost), "net.msg" (from, tbl, meta) for a message from a lobby member, "net.peer" (id, up).
do
  local CHANNEL_VERSION = 1
  local PRESENCE_TITLE = 60          -- characters of the party title in the presence (the whole table is <= 256 B)
  -- Pacing per destination, below the core limits (20 msg/s, 8 KB/s, burst 10) so queue pages never hit "rate".
  local OUT_MSGS, OUT_BYTES = 8, 6000

  local ch, openTried, openWhy = nil, -1e9, nil
  local lobby, signature = nil, ""
  local presenceMine, presenceSent = {}, nil
  local outbox = {}                  -- id -> {list = {{tbl, opts, key, bytes}}, win = start ms, n, bytes}

  ---------------------------------------------------------------- lobby

  function NET.inSession() return lobby ~= nil end
  function NET.me() return lobby and lobby.me end
  function NET.phase() return lobby and lobby.phase end
  function NET.lobby() return lobby end

  -- The party host is always the lobby owner. Without a net session this machine hosts a solo party.
  function NET.isHost() return lobby == nil or lobby.owner == lobby.me end
  function NET.hostId() return lobby and lobby.owner end

  function NET.member(id)
    if not lobby then return nil end
    for _, m in ipairs(lobby.members or {}) do
      if m.id == id then return m end
    end
  end

  function NET.name(id)
    local m = NET.member(id)
    return m and type(m.name) == "string" and U.trim(m.name, 32) or "?"
  end

  -- A presence table another member published, checked field by field: {pack = "ready"|"missing"|"downloading",
  -- progress = 0..100, party = bool, title = string, n = 0..200}. Anything else is dropped; a non-table gives nil.
  function NET.parsePresence(t)
    if type(t) ~= "table" then return nil end
    local out = {}
    if type(t.pack) == "string" then
      if t.pack == "ready" or t.pack == "missing" then
        out.pack = t.pack
      else
        local pct = t.pack:match("^downloading:(%d%d?%d?)$")
        if pct and tonumber(pct) <= 100 then out.pack, out.progress = "downloading", tonumber(pct) end
      end
    end
    if t.party == 1 or t.party == true then out.party = true end
    if out.party and type(t.title) == "string" then out.title = U.trim(t.title, PRESENCE_TITLE) end
    local n = U.num(t.n)
    if out.party and n then out.n = math.floor(U.clamp(n, 0, 200)) end
    return out
  end

  function NET.presence(id)
    if not ch then return nil end
    local ok, t = pcall(ch.presence, ch, id)
    return ok and NET.parsePresence(t) or nil
  end

  function NET.clock(id)
    if not ch then return nil end
    local ok, c = pcall(ch.clock, ch, id)
    if ok and type(c) == "table" then return c end
  end

  -- {{id, name, holo, pack, progress, rtt, me, host, party}} in lobby order; empty outside a session.
  function NET.members()
    local out = {}
    if not lobby then return out end
    for _, m in ipairs(lobby.members or {}) do
      if type(m.id) == "string" then
        local pr = (not m.me) and NET.presence(m.id) or nil
        local c = (not m.me) and NET.clock(m.id) or nil
        out[#out + 1] = {id = m.id, name = U.trim(m.name, 32), me = m.me == true, host = m.id == lobby.owner,
          holo = m.me == true or m.peer == true or pr ~= nil,
          pack = m.me and presenceMine.packState or (pr and pr.pack),
          progress = pr and pr.progress, rtt = c and U.num(c.rtt) and math.floor(c.rtt + 0.5) or nil,
          party = pr and pr.party or nil}
      end
    end
    return out
  end

  local function sign()
    if not lobby then return "" end
    local parts = {tostring(lobby.owner), tostring(lobby.phase)}
    for _, m in ipairs(lobby.members or {}) do
      local pr = (not m.me) and NET.presence(m.id) or nil
      parts[#parts + 1] = tostring(m.id) .. (m.peer and "+" or "-") .. (pr and tostring(pr.pack) .. tostring(pr.party)
        .. tostring(pr.progress) .. tostring(pr.title) .. tostring(pr.n) or "")
    end
    return table.concat(parts, "|")
  end

  function NET.refresh()
    local ok, st = pcall(wum.lobby.state)
    lobby = ok and type(st) == "table" and st or nil
    if lobby and type(lobby.members) ~= "table" then lobby.members = {} end
    local s = sign()
    if s ~= signature then
      signature = s
      U.emit("lobby.changed")
    end
  end

  ---------------------------------------------------------------- channel

  function NET.channel() return ch end
  function NET.available() return ch ~= nil, openWhy end

  local function onMessage(from, tbl, meta)
    if type(from) ~= "string" or type(tbl) ~= "table" or type(tbl.t) ~= "string" then return end
    if not NET.member(from) or from == NET.me() then return end   -- the core filters too; cheap to repeat
    U.emit("net.msg", from, tbl, type(meta) == "table" and meta or {})
  end

  local function open()
    openTried = U.now()
    local c, why = wum.peer.open{version = CHANNEL_VERSION}
    if not c then
      openWhy = why
      return
    end
    ch, openWhy = c, nil
    ch:on(U.guard("net.on", onMessage))
    ch:onPeer(U.guard("net.onPeer", function(id, up)
      if not up then outbox[id] = nil end
      U.emit("net.peer", id, up)
    end))
    presenceSent = nil
  end

  function NET.peers()
    if not ch then return {} end
    local ok, p = pcall(ch.peers, ch)
    return ok and type(p) == "table" and p or {}
  end

  function NET.reachable(id)
    for _, p in ipairs(NET.peers()) do
      if p == id then return true end
    end
    return false
  end

  -- Rough size of a table on the wire (the core's tagged binary), for the outbox pacing and the page split.
  local function sizeOf(v, depth)
    local t = type(v)
    if t == "string" then return 3 + #v end
    if t == "number" then return 9 end
    if t ~= "table" then return 1 end
    if (depth or 0) > 8 then return 1 end
    local n = 3
    for k, x in pairs(v) do n = n + sizeOf(k, 9) + sizeOf(x, (depth or 0) + 1) end
    return n
  end
  NET.sizeOf = sizeOf

  -- Sends at once: true, or false and a reason ("closed" without a channel). Unreliable when opts.reliable == false.
  function NET.send(id, tbl, opts)
    if not ch then return false, "closed" end
    local ok, r, why = pcall(ch.send, ch, id, tbl, opts)
    if not ok then return false, tostring(r) end
    return r, why
  end

  -- Queues a reliable message to one member, paced per destination. A message with a key replaces a queued one with
  -- the same key (a newer state supersedes an older one that has not left yet).
  function NET.post(id, tbl, key)
    local box = outbox[id]
    if not box then
      box = {list = {}, win = U.now(), n = 0, bytes = 0}
      outbox[id] = box
    end
    if key then
      for _, m in ipairs(box.list) do
        if m.key == key then
          m.tbl, m.bytes = tbl, sizeOf(tbl)
          return
        end
      end
    end
    box.list[#box.list + 1] = {tbl = tbl, key = key, bytes = sizeOf(tbl)}
  end

  -- Drops the queued messages to `id` whose key matches a Lua pattern (an older queue's pages).
  function NET.drop(id, pattern)
    local box = outbox[id]
    if not box then return end
    for i = #box.list, 1, -1 do
      local k = box.list[i].key
      if k and k:find(pattern) then table.remove(box.list, i) end
    end
  end

  -- NET.post to every member reachable now; returns how many.
  function NET.postAll(tbl, key)
    local peers = NET.peers()
    for _, id in ipairs(peers) do NET.post(id, tbl, key) end
    return #peers
  end

  function NET.pending(id)
    local box = outbox[id]
    return box and #box.list or 0
  end

  local function drain()
    local now = U.now()
    for id, box in pairs(outbox) do
      if now - box.win >= 1000 then box.win, box.n, box.bytes = now, 0, 0 end
      while box.list[1] and box.n < OUT_MSGS and (box.bytes + box.list[1].bytes <= OUT_BYTES or box.n == 0) do
        local m = box.list[1]
        local ok, why = NET.send(id, m.tbl)
        if not ok and why == "rate" then
          box.n = OUT_MSGS                                     -- try again in the next window
          break
        end
        table.remove(box.list, 1)
        box.n, box.bytes = box.n + 1, box.bytes + m.bytes
        if not ok then U.log("debug", "send", m.tbl.t, "failed:", why) end
      end
      if not box.list[1] then outbox[id] = nil end
    end
  end

  ---------------------------------------------------------------- presence

  -- Merges fields into this machine's presence (nil removes one) and publishes it when it changed. packState is
  -- kept for NET.members() and published as the "pack" field.
  function NET.setPresence(fields)
    for k, v in pairs(fields) do presenceMine[k] = v end
    if not ch then return end
    local pub = {pack = presenceMine.pack}
    if presenceMine.party then
      pub.party = 1
      pub.title = U.trim(presenceMine.title, PRESENCE_TITLE)
      pub.n = presenceMine.n
    end
    local s = tostring(pub.pack) .. "|" .. tostring(pub.party) .. "|" .. tostring(pub.title) .. "|" .. tostring(pub.n)
    if s == presenceSent then return end
    presenceSent = s
    pcall(ch.setPresence, ch, pub)
  end

  function NET.myPresence() return presenceMine end

  -- The pack state for the presence: "ready", "missing" or "downloading:<percent>".
  function NET.packPresence(pk)
    if type(pk) ~= "table" then return "missing" end
    if pk.state == "ready" then return "ready" end
    if pk.state == "downloading" or pk.state == "verifying" or pk.state == "installing" or pk.state == "updating" then
      return "downloading:" .. math.floor(U.clamp(U.num(pk.progress) or 0, 0, 1) * 100)
    end
    return "missing"
  end

  local function updatePack()
    local ok, pk = pcall(wum.media.pack)
    local s = NET.packPresence(ok and pk or nil)
    if s ~= presenceMine.pack then
      NET.setPresence{pack = s, packState = s:match("^%a+")}
    end
  end

  ---------------------------------------------------------------- events and tick

  local function lobbyEvent(kind)
    return U.guard("net." .. kind, function()
      NET.refresh()
      if kind == "leave" then
        outbox = {}
        U.emit("net.leave")
      elseif kind == "enter" then
        presenceSent = nil
        U.emit("net.enter")
      elseif kind == "owner" then
        outbox = {}
        U.emit("net.owner", lobby and lobby.owner, NET.isHost())
      end
    end)
  end
  wum.events.on("melange.lobby.enter", lobbyEvent("enter"))
  wum.events.on("melange.lobby.leave", lobbyEvent("leave"))
  wum.events.on("melange.lobby.owner", lobbyEvent("owner"))
  wum.events.on("melange.lobby.members", lobbyEvent("members"))
  wum.events.on("melange.lobby.phase", lobbyEvent("phase"))

  local lastRefresh = -1e9
  function NET.tick()
    local now = U.now()
    if not ch and now - openTried >= 5000 then open() end
    if now - lastRefresh >= 500 then
      lastRefresh = now
      NET.refresh()
      updatePack()
    end
    drain()
  end

  open()
  NET.refresh()
  updatePack()
  wum.timers.every(0, U.guard("net", NET.tick))
end

-- ==== src/40_party.lua ====
-- party (P2): role and phase, the host's authoritative state and the sync protocol of design 2.5 over NET.
-- Star topology: the party host is always the lobby owner; peers talk to the owner only and the owner fans out.
-- Bus events: "party.changed", "party.toast" (text, kind), "party.joinPrompt" (hostName, autoJoined),
-- "party.continuePrompt" (hostName), "party.memberHi" (id; host: a member said "hi"), "party.addResult" (ok, why,
-- count, title; peer: the host answered an add), "party.addSent" (title; peer: a pick went to the host).
-- Members add to the queue with "add" -> the host checks it (QUEUE.addFor) and answers "addr"; "cap" tells a member
-- what the host accepts, "rm" removes an item the member added. All are ignored by Holo 1.0.x.
do
  local PLAY_LEAD = 300              -- ms: play and resume are scheduled this far ahead so peers start together
  local HEARTBEAT = 1000             -- ms between unreliable "st" while playing
  local HI_EVERY = 10000             -- ms between "hi" until the host answers
  local HI_ACCEPT, NEED_ACCEPT = 2000, 5000   -- host: one "hi" per member per 2 s, one "need" per 5 s (N3)
  local OPEN_EVERY = 1500            -- peer: one item open per 1.5 s, coalesced to the latest item (N3)
  local NEED_EVERY = 3000            -- peer: how often it asks for a queue it is missing
  local SCRUB_HOLD = 2000            -- host: no heartbeat this long after a keyframes (scrub) seek, unless it ends
  local MUSIC_RETRY = 2000           -- ms between retries of a refused wum.audio.music.suppress
  local ADD_ACCEPT, RM_ACCEPT = 1500, 500   -- host: one "add" per member per 1.5 s, one "rm" per 0.5 s
  local ADD_EVERY = 1000             -- peer: one add request per second
  local ADD_WAIT = 45000             -- peer: how long it waits for the host's "addr" before giving up
  local SPEEDS = {0.5, 0.75, 1, 1.25, 1.5, 2}
  local QUALITIES = {[360] = true, [480] = true, [720] = true, [1080] = true}
  PARTY.SPEEDS = SPEEDS

  local role, phase, setupOpen = "none", "idle", false
  local player, pstate, openedId, openedUrl, loaded = nil, nil, nil, nil, false
  local hs = nil                     -- the host's state {e, i, s, p, r, a}; on a peer the last valid "st"
  local epoch = 0
  local pendingPlayAt, autoplay, ended, errorAt = nil, false, false, nil
  local lastBeat, queueDirtyAt = -1e9, nil
  local needsPack = false
  -- peer side
  local hostParty, declined, prompted, acked = false, false, false, false
  local lastHi, lastOpen, lastNeed, wantOpen = -1e9, -1e9, -1e9, nil
  local hostCaps = nil               -- the host's last "cap" {add, music, madd}; nil from a host without Holo 1.1
  local pendingAdds, nextAddN, lastAddAt = {}, 1, -1e9   -- n -> {at}: adds the host has not answered yet
  -- host side: what each member told us
  local info = {}                    -- id -> {hiAt, needAt, holo, buf, err, loaded}
  local resume, musicOn = nil, false
  local musicFailAt, musicWarned = nil, false
  local scrubAt = nil                -- host: the last keyframes seek; the scrub position stays local (design 2.5)
  local applied = {}                 -- the volume and mute last sent to the player

  ---------------------------------------------------------------- small reads

  function PARTY.role() return role end
  function PARTY.active() return role ~= "none" end
  function PARTY.player() return player end
  function PARTY.state() return pstate end
  function PARTY.hostState() return hs end
  function PARTY.currentUrl() return openedUrl end
  function PARTY.currentId() return openedId end
  function PARTY.canContinue() return resume ~= nil and role == "none" and NET.isHost() end
  -- A party the lobby owner runs that this machine has not joined (or declined).
  function PARTY.partyRunning()
    if role ~= "none" or NET.isHost() then return false end
    if hostParty then return true end
    local pr = NET.presence(NET.hostId())
    return pr ~= nil and pr.party == true
  end
  function PARTY.declined() return declined end

  -- The host controls the party; before a party, the lobby owner (or anyone without a lobby) sets it up.
  function PARTY.canControl()
    if role == "host" then return true end
    return role == "none" and NET.isHost()
  end

  function PARTY.hostCaps() return hostCaps end
  -- True once the lobby owner's Holo answered this machine's "hi" (any version).
  function PARTY.hostAcked() return acked end

  -- True if this machine may add to the video queue now: it controls the party, or the lobby owner runs a 1.1 party
  -- that accepts adds.
  function PARTY.canAdd()
    if PARTY.canControl() then return true end
    if not NET.inSession() or NET.isHost() then return false end
    return hostCaps ~= nil and hostCaps.add == true and (role == "peer" or PARTY.partyRunning())
  end

  -- Why a member cannot add: "not-running" | "old-host" | "host-only" | "no-host" | nil (it can, or no lobby).
  function PARTY.addWhyNot()
    if PARTY.canAdd() then return nil end
    if not NET.inSession() then return nil end
    if not (PARTY.partyRunning() or role == "peer") then return "not-running" end
    if not NET.reachable(NET.hostId()) then return "no-host" end
    if acked and not hostCaps then return "old-host" end
    if hostCaps and hostCaps.add == false then return "host-only" end
    return "no-host"
  end

  function PARTY.hostName()
    if not NET.inSession() or NET.isHost() then return "you" end
    return NET.name(NET.hostId())
  end

  local function toast(text, kind) U.emit("party.toast", text, kind or "info") end

  local function inSession() return NET.inSession() end

  ---------------------------------------------------------------- music, audio prefs

  local function applyMusic()
    local music = wum.audio and wum.audio.music
    if not music then return end
    -- Game music stays silent for a party and while the music lane (MUSIC, Part B) is audible. Always a boolean.
    local want = (role ~= "none" or (MUSIC ~= nil and MUSIC.audible ~= nil and MUSIC.audible() == true))
      and CFG.get("musicOff") == true
    if want == musicOn then return end
    -- A refused request ("unavailable" before the audio hook is in, "disabled") is retried from the tick.
    local now = U.now()
    if musicFailAt and now - musicFailAt < MUSIC_RETRY then return end
    local ok, res, why = pcall(music.suppress, want, {fade = 0.4})
    if ok and res then
      musicOn, musicFailAt = want, nil
      return
    end
    musicFailAt = now
    if want and ok and why == "disabled" and not musicWarned then
      musicWarned = true
      toast("The game music stays on: AllowMusicSuppress is off in Melange.ini")
    end
  end

  local function volume() return math.floor(U.clamp(U.num(U.pref("volume", CFG.get("volume"))) or 70, 0, 100)) end
  local function userMute() return U.pref("mute", false) == true end
  local function quality()
    local q = math.tointeger(U.pref("quality")) or math.tointeger(tonumber(CFG.get("quality"))) or 720
    return QUALITIES[q] and q or 720
  end
  local function lang(key)
    local l = U.pref(key)
    if type(l) == "string" and (l:match("^%l%l%l?$") or l:match("^%l%l%l?%-%w%w%w?%w?%w?%w?%w?%w?$")) then return l end
  end

  local function effectiveMute()
    if userMute() then return true end
    return CFG.get("hiddenMutes") == true and LAYOUT.view and LAYOUT.view() == "hidden"
  end

  local function applyAudio()
    if not player then return end
    local v, m = volume(), effectiveMute()
    if applied.v ~= v then applied.v = v; player:volume(v) end
    if applied.m ~= m then applied.m = m; player:mute(m) end
  end

  function PARTY.volume() return volume() end
  function PARTY.muted() return userMute() end
  function PARTY.quality() return quality() end

  function PARTY.setVolume(v)
    v = U.num(v)
    if not v then return nil, "volume" end
    U.setPref("volume", math.floor(U.clamp(v, 0, 100) + 0.5))
    applyAudio()
    return true
  end

  function PARTY.setMute(b)
    U.setPref("mute", b == true)
    applyAudio()
    return true
  end

  function PARTY.setQuality(h)
    h = math.tointeger(h) or math.tointeger(tonumber(h))
    if not QUALITIES[h] then return nil, "quality" end
    U.setPref("quality", h)
    if player then player:quality(h) end
    return true
  end

  -- Subtitles and audio are per player and not synced; the choice is remembered by language.
  function PARTY.setTrack(kind, id)
    if kind ~= "audio" and kind ~= "sub" then return nil, "kind" end
    if not player then return nil, "no-player" end
    local ok, why = player:track(kind, id)
    if not ok then return nil, why end
    local key = kind == "audio" and "audioLang" or "subLang"
    if id == false then
      U.setPref(key, false)
    else
      for _, t in ipairs(pstate and pstate.tracks and pstate.tracks[kind] or {}) do
        if t.id == id and type(t.lang) == "string" then U.setPref(key, t.lang) end
      end
    end
    return true
  end

  ---------------------------------------------------------------- the player

  -- Closes the player. openedId/openedUrl stay: they name the item this machine is on, playing or not.
  local function closePlayer()
    if player then pcall(player.close, player) end
    player, pstate, loaded = nil, nil, false
    applied = {}
  end

  -- Opens a queue item paused at `start`. Returns the player, or nil and a reason ("wait" while a torrent's file
  -- list is still coming).
  local function openItem(it, start, paused)
    closePlayer()
    local o = {start = start or 0, paused = paused ~= false, volume = volume(), mute = effectiveMute(),
      quality = quality(), speed = hs and hs.r or 1, audioLang = lang("audioLang"), subLang = lang("subLang")}
    if it.kind == "bt" then
      local e, why = QUEUE.torrentFor(it.url)
      if not e then return nil, why end
      if e.error then return nil, "torrent" end
      if not e.files then return nil, "wait" end
      o.torrent, o.file = e.t, it.file
    else
      o.url = it.url
    end
    local p, why = wum.media.open(o)
    if not p then return nil, why end
    player, openedId, openedUrl, loaded = p, it.id, it.url, false
    applied = {v = o.volume, m = o.mute}
    if it.kind == "bt" then QUEUE.keepTorrents(it.url) end
    if LAYOUT.sizeHint then
      local w, h = LAYOUT.sizeHint()
      if w then p:size(w, h) end
    end
    return p
  end

  local function curPos()
    if player then
      local ok, st = pcall(player.state, player)
      if ok and st and U.num(st.time) then return st.time end
    end
    if hs then
      local p = hs.p
      if hs.s == "play" then p = p + math.max(0, U.now() - hs.a) / 1000 * hs.r end
      return p
    end
    return 0
  end
  PARTY.position = curPos

  ---------------------------------------------------------------- host: state and fan-out

  local function stMsg(h) return {t = "st", e = h.e, i = h.i, s = h.s, p = h.p, r = h.r, a = h.a} end

  local function broadcastState(reliable)
    if role ~= "host" or not hs or not inSession() then return end
    local m = stMsg(hs)
    if reliable == false then
      for _, id in ipairs(NET.peers()) do NET.send(id, m, {reliable = false}) end
    else
      NET.postAll(m, "st")
    end
  end

  local function setState(s, p, a)
    epoch = epoch + 1
    hs = {e = epoch, i = openedId or (hs and hs.i) or 0, s = s, p = math.max(0, p), r = hs and hs.r or 1,
      a = a or U.now()}
    broadcastState(true)
  end

  local function presence()
    if role == "host" then
      local it = QUEUE.current()
      NET.setPresence{party = true, title = it and it.title or "", n = QUEUE.count()}
    else
      NET.setPresence{party = false, title = nil, n = nil}
    end
  end

  -- What the host tells members it accepts: video adds (a running party with whoAdds "anyone"), the music lane, and
  -- music adds (whoAdds "anyone", with or without a video party).
  local function capMsg()
    local anyone = CFG.get("whoAdds") == "anyone"
    return {t = "cap", add = role == "host" and anyone, music = true, madd = anyone}
  end

  local function broadcastCaps()
    if inSession() and NET.isHost() then NET.postAll(capMsg(), "cap") end
  end

  local function sendQueue(id)
    if id then NET.drop(id, "^q%d") else for _, p in ipairs(NET.peers()) do NET.drop(p, "^q%d") end end
    for _, page in ipairs(QUEUE.pages()) do
      if id then NET.post(id, page, "q" .. page.page) else NET.postAll(page, "q" .. page.page) end
    end
  end

  local function sendTorrentInfo(id)
    local it = QUEUE.current()
    if not (it and it.kind == "bt") then return end
    local c = wum.media.classify(it.url)
    local m = {t = "bt", id = it.id, ih = c and c.infohash, f = it.file}
    if id then NET.post(id, m) else NET.postAll(m) end
  end

  local function schedulePlay(pos)
    pendingPlayAt = U.now() + PLAY_LEAD
    setState("play", pos, pendingPlayAt)
  end

  local playItem

  -- The host's next item after the current one ended or failed; past the end the party waits ("ended-item").
  local function advance()
    local nxt = QUEUE.step(1)
    if nxt then
      playItem(nxt, 0)
    else
      ended = true
      pendingPlayAt = nil
      setState("pause", curPos())
    end
  end

  function playItem(it, start)
    ended, errorAt, pendingPlayAt = false, nil, nil
    QUEUE.setCurrent(it.id)
    hs = hs or {r = 1}
    local p, why = openItem(it, start, true)
    openedId, openedUrl = it.id, it.url
    hs.i = it.id
    autoplay = true
    if not p then
      if why == "wait" then
        wantOpen = it.id                -- the torrent's file list is still coming; the tick retries
      else
        toast(why == "cache-cap" and "This file is larger than the video cache" or "Can't play this item", "error")
        errorAt = U.now()
      end
    end
    setState("pause", start or 0)
    presence()
  end

  local function startAt(it, start)
    if not it then return nil, "empty" end
    local pk = wum.media.pack()
    if not (pk and pk.state == "ready") then return nil, "pack" end
    role, resume, declined = "host", nil, false
    epoch = epoch + 1
    hs = {r = 1}
    info = {}
    applyMusic()
    if inSession() then
      NET.postAll({t = "ack", party = true, qv = QUEUE.version()}, "ack")
      broadcastCaps()
      sendQueue()
    end
    playItem(it, start or 0)
    U.emit("party.changed")
    return true
  end

  -- Starts the party from the queue's current item (or its first). The lobby owner only; needs the pack.
  function PARTY.start()
    if role ~= "none" then return nil, "active" end
    if not NET.isHost() then return nil, "not-host" end
    if QUEUE.count() == 0 then return nil, "empty" end
    return startAt(QUEUE.current() or QUEUE.items()[1], 0)
  end

  local function endLocal()
    local wasHost = role == "host"
    closePlayer()
    openedId, openedUrl = nil, nil
    QUEUE.closeAllTorrents()
    role, hs, ended, needsPack, pendingPlayAt, autoplay, wantOpen, errorAt = "none", nil, false, false, nil, false,
      nil, nil
    if wasHost then broadcastCaps() end          -- add = false now
    applyMusic()
    presence()
    U.emit("party.changed")
  end

  -- Host: ends the party for everyone. Peer: leaves it (like declining).
  function PARTY.stop()
    if role == "host" then
      if inSession() then NET.postAll({t = "end", why = "host"}) end
      endLocal()
      return true
    elseif role == "peer" then
      return PARTY.decline()
    end
    return false
  end

  local function hostOnly()
    if role ~= "host" then return nil, "not-host" end
    if not player and not ended then return nil, "no-player" end
    return true
  end

  function PARTY.togglePlay()
    local ok, why = hostOnly()
    if not ok then return nil, why end
    autoplay = false                    -- the host decided; a pending load no longer starts by itself
    if hs.s == "play" then
      local pos = curPos()
      pendingPlayAt = nil
      if player then player:pause() end
      setState("pause", pos)
    else
      local pos = curPos()
      if ended or (pstate and pstate.eof) then
        ended, pos = false, 0
        if player then player:seek(0, "exact") end
      end
      schedulePlay(pos)
    end
    U.emit("party.changed")
    return true
  end

  -- mode "keyframes" while scrubbing (local only), "exact" on release (sent to the peers).
  function PARTY.seek(t, mode)
    local ok, why = hostOnly()
    if not ok then return nil, why end
    t = U.num(t)
    if not t or not player then return nil, "seek" end
    local dur = pstate and U.num(pstate.duration)
    if dur and dur > 0 then t = math.min(t, dur) end
    t = math.max(0, t)
    if mode == "keyframes" then
      player:seek(t, "keyframes")
      scrubAt = U.now()
      return true
    end
    scrubAt = nil
    player:seek(t, "exact")
    ended = false
    if pendingPlayAt then
      schedulePlay(t)                   -- the play had not started yet: keep the lead
    elseif hs.s == "play" then
      setState("play", t)
    else
      setState("pause", t)
    end
    return true
  end

  function PARTY.skip(delta)
    local d = U.num(delta)
    if not d then return nil, "seek" end
    return PARTY.seek(curPos() + d, "exact")
  end

  function PARTY.next()
    if role ~= "host" then return nil, "not-host" end
    local nxt = QUEUE.step(1)
    if not nxt then return nil, "end" end
    playItem(nxt, 0)
    return true
  end

  function PARTY.prev()
    if role ~= "host" then return nil, "not-host" end
    if player and curPos() > 5 then return PARTY.seek(0, "exact") end
    local prv = QUEUE.step(-1)
    if not prv then return PARTY.seek(0, "exact") end
    playItem(prv, 0)
    return true
  end

  -- Snaps to the nearest synced speed (0.5 to 2).
  function PARTY.setSpeed(x)
    if role ~= "host" then return nil, "not-host" end
    x = U.num(x)
    if not x then return nil, "speed" end
    local best = 1
    for _, s in ipairs(SPEEDS) do
      if math.abs(s - x) < math.abs(best - x) then best = s end
    end
    if player then player:speed(best) end
    local pos = curPos()
    hs.r = best
    setState(hs.s, pos, pendingPlayAt)
    return true
  end

  ---------------------------------------------------------------- peer side

  local function sendHost(m)
    local host = NET.hostId()
    if not host then return false end
    NET.post(host, m)
    return true
  end

  -- Peer: asks the host to add a link. f = {u, f?, ti?}: u the canonical link, f the torrent file index, ti its title.
  -- Returns true, "sent" (the answer comes as "party.addResult"), or nil and "rate" | "no-host".
  function PARTY.requestAdd(f)
    local now = U.now()
    if now - lastAddAt < ADD_EVERY then return nil, "rate" end
    local host = NET.hostId()
    if not host or not NET.reachable(host) then return nil, "no-host" end
    local n = nextAddN
    nextAddN = nextAddN + 1
    pendingAdds[n] = {at = now}
    lastAddAt = now
    NET.post(host, {t = "add", n = n, u = f.u, f = f.f, ti = f.ti and U.trim(f.ti, 120)}, "add" .. n)
    return true, "sent"
  end

  -- Peer: asks the host to remove an item this machine added. true, or nil and a reason.
  function PARTY.requestRemove(id)
    local me = NET.me()
    local it = QUEUE.find(id)
    if not it or me == nil or it.byId ~= me then return nil, "not-yours" end
    local host = NET.hostId()
    if not host or not NET.reachable(host) then return nil, "no-host" end
    if not hostCaps then return nil, "old-host" end
    NET.post(host, {t = "rm", id = id})
    return true
  end

  local function packReady()
    local pk = wum.media.pack()
    return pk ~= nil and pk.state == "ready"
  end

  local function hostNow()
    local c = NET.clock(NET.hostId())
    return U.now() + (c and U.num(c.offset) or 0)
  end

  -- Applies the latest host state: open the item when it changed (paced), else follow.
  local function applySt()
    if role ~= "peer" or not hs then return end
    if needsPack then return end
    if hs.i ~= openedId then
      if QUEUE.find(hs.i) then
        wantOpen = hs.i
      elseif U.now() - lastNeed >= NEED_EVERY then
        lastNeed = U.now()
        sendHost{t = "need", qv = QUEUE.version()}
      end
      return
    end
    if player then player:follow(hs, NET.hostId()) end
  end

  local function openWanted()
    local it = QUEUE.find(wantOpen)
    if not it then
      wantOpen = nil
      return
    end
    local start = hs.p
    if hs.s == "play" then start = start + math.max(0, hostNow() - hs.a) / 1000 * hs.r end
    local p, why = openItem(it, math.max(0, start), hs.s ~= "play")
    if not p then
      if why == "wait" then return end   -- the torrent's file list is still coming
      wantOpen = nil
      if why == "pack" then
        needsPack = true                  -- opened again once the pack is ready
      else
        openedId, openedUrl = it.id, it.url -- this item failed here; do not retry it on every "st"
        toast(why == "first-use-in-match" and "Torrent items can start only in the menus or the lobby"
          or "Can't play this item here", "error")
        sendHost{t = "buf", b = false, i = it.id, p = 0, ok = false}
      end
      U.emit("party.changed")
      return
    end
    wantOpen = nil
    QUEUE.setCurrent(it.id)
    p:follow(hs, NET.hostId())
  end

  function PARTY.join()
    if role ~= "none" then return nil, "active" end
    if NET.isHost() or not PARTY.partyRunning() then return nil, "no-party" end
    role, declined = "peer", false
    U.setPref("autoJoin", true)
    needsPack = not packReady()
    applyMusic()
    if QUEUE.count() == 0 or not hs then
      lastNeed = U.now()
      sendHost{t = "need", qv = QUEUE.version()}
    end
    applySt()
    U.emit("party.changed")
    return true
  end

  -- "Not now": leaves the running party (or refuses the prompt) and remembers it; the next party prompts again.
  function PARTY.decline()
    declined = true
    U.setPref("autoJoin", false)
    if role == "peer" then endLocal() end
    U.emit("party.changed")
    return true
  end

  local function hostRunning()
    if hostParty then return end
    hostParty = true
    if role ~= "none" or declined or prompted then return end
    prompted = true
    if U.pref("autoJoin", true) ~= false then
      PARTY.join()
      U.emit("party.joinPrompt", PARTY.hostName(), true)
    else
      U.emit("party.joinPrompt", PARTY.hostName(), false)
    end
  end

  -- A new owner that had the queue continues where the old host stopped.
  function PARTY.continueParty()
    if not PARTY.canContinue() then return nil, "nothing" end
    local snap = resume
    local cur = QUEUE.load(snap.snap)
    local it = (cur and QUEUE.find(cur)) or QUEUE.items()[1]
    if not it then
      resume = nil
      return nil, "empty"
    end
    local r = snap.rate or 1
    local ok, why = startAt(it, it.id == cur and snap.time or 0)
    if ok and r ~= 1 then PARTY.setSpeed(r) end
    return ok, why
  end

  -- Loads the queue stored by the last party this machine hosted (only while idle).
  function PARTY.restoreLastQueue()
    if role ~= "none" or not PARTY.canControl() then return nil, "active" end
    local snap = U.pref("lastQueue")
    if type(snap) ~= "table" then return nil, "nothing" end
    QUEUE.load(snap)
    return true
  end

  ---------------------------------------------------------------- message validation

  -- A "st" from the host, checked: returns the clean state or nil.
  function PARTY.checkSt(m)
    if type(m) ~= "table" then return nil end
    local e, i, p, r, a = m.e, m.i, U.num(m.p), U.num(m.r), U.num(m.a)
    if math.type(e) ~= "integer" or e < 0 or math.type(i) ~= "integer" or i < 0 then return nil end
    if m.s ~= "play" and m.s ~= "pause" then return nil end
    if not p or p < 0 or p > 1e7 or not r or r < 0.25 or r > 4 or not a then return nil end
    return {e = e, i = i, s = m.s, p = p, r = r, a = a}
  end

  local function newer(a, b)
    if not b then return true end
    if a.e ~= b.e then return a.e > b.e end
    return a.a >= b.a
  end

  local function fromHost(from, m)
    local t = m.t
    if t == "ack" then
      acked = true
      if m.party == true then
        hostRunning()
      elseif hostParty or role == "peer" then
        hostParty = false
        if role == "peer" then endLocal() end
      end
    elseif t == "q" then
      local done = QUEUE.acceptPage(m)
      if done then
        hostRunning()
        applySt()
      end
    elseif t == "st" then
      local st = PARTY.checkSt(m)
      if not st or not newer(st, hs) then return end
      hs = st
      hostRunning()
      applySt()
    elseif t == "bt" then
      local it = QUEUE.find(m.id)
      local c = it and wum.media.classify(it.url)
      if c and c.infohash == m.ih then QUEUE.setFile(m.id, m.f) end
    elseif t == "cap" then
      hostCaps = {add = m.add == true, music = m.music == true, madd = m.madd == true}
      U.emit("party.changed")
    elseif t == "addr" then
      local p = pendingAdds[m.n]
      if not p then return end
      pendingAdds[m.n] = nil
      U.emit("party.addResult", m.ok == true, type(m.why) == "string" and U.trim(m.why, 24) or nil,
        math.type(m.c) == "integer" and m.c or nil, type(m.ti) == "string" and U.trim(m.ti, 60) or nil)
    elseif t == "end" then
      local was = role == "peer"
      hostParty, declined, prompted = false, false, false
      if was then
        endLocal()
        toast("The host ended the watch party")
      end
      U.emit("party.changed")
    end
  end

  local function fromMember(from, m)
    local t = m.t
    local now = U.now()
    local mi = info[from]
    if not mi then
      mi = {hiAt = -1e9, needAt = -1e9}
      info[from] = mi
    end
    if t == "hi" then
      if now - mi.hiAt < HI_ACCEPT then return end
      mi.hiAt = now
      mi.holo = U.trim(m.holo, 16)
      NET.post(from, {t = "ack", party = role == "host", qv = QUEUE.version()}, "ack")
      NET.post(from, capMsg(), "cap")
      if role == "host" then
        sendQueue(from)
        if hs then NET.post(from, stMsg(hs), "st") end
        sendTorrentInfo(from)
      end
      U.emit("party.memberHi", from)
    elseif t == "add" then
      local n = m.n
      if math.type(n) ~= "integer" or n < 1 or n > 2147483647 then return end
      local function reply(ok, why, c, ti)
        NET.post(from, {t = "addr", n = n, ok = ok, why = why, c = c, ti = ti and U.trim(ti, 60)})
      end
      if role ~= "host" then return reply(false, "not-running") end
      if CFG.get("whoAdds") ~= "anyone" then return reply(false, "host-only") end
      if now - (mi.addAt or -1e9) < ADD_ACCEPT then return reply(false, "rate") end
      mi.addAt = now
      if type(m.u) ~= "string" or #m.u > 4096 then return reply(false, "unsupported-url") end
      local c = wum.media.classify(m.u)
      if not c then return reply(false, "unsupported-url") end
      local f = m.f
      if math.type(f) ~= "integer" or f < 0 or f > 100000 then f = nil end
      local name = U.trim(NET.name(from), 32)
      QUEUE.addFor(c, {by = name, byId = from, f = f, ti = m.ti}, function(ok, why, count, title)
        reply(ok, why, count, title)
        if ok and U.now() - (mi.toastAt or -1e9) >= 3000 then
          mi.toastAt = U.now()
          toast(name .. " added " .. (count and count > 1 and (count .. " videos") or U.trim(title or "a video", 60)))
        end
      end)
    elseif t == "rm" then
      if role ~= "host" or math.type(m.id) ~= "integer" or now - (mi.rmAt or -1e9) < RM_ACCEPT then return end
      mi.rmAt = now
      QUEUE.removeFor(m.id, from)
    elseif t == "need" then
      if role ~= "host" or now - mi.needAt < NEED_ACCEPT then return end
      mi.needAt = now
      sendQueue(from)
      if hs then NET.post(from, stMsg(hs), "st") end
    elseif t == "buf" then
      if type(m.b) ~= "boolean" then return end
      mi.buf = m.b
      mi.err = m.ok == false
      if m.ok == true then mi.loaded = true end
    end
  end

  U.on("net.msg", function(from, m)
    if from == NET.hostId() and not NET.isHost() then
      fromHost(from, m)
    elseif NET.isHost() and inSession() then
      fromMember(from, m)
    end
  end)

  U.on("net.peer", function(id, up)
    if id == NET.hostId() and not NET.isHost() then
      acked = false
      if up then lastHi = -1e9 end
    elseif info[id] and not up then
      info[id].buf = false
    end
  end)

  ---------------------------------------------------------------- lobby changes

  local function resetPeerSide()
    hostParty, declined, prompted, acked = false, false, false, false
    lastHi, wantOpen = -1e9, nil
    hostCaps, pendingAdds = nil, {}
    info = {}
    if role == "none" then hs = nil end
    -- A peer forgets the host's queue version, so the next host's pages are taken whatever their number. An owner
    -- keeps its own counter (a peer's mirror never shares it after this reset).
    if not NET.isHost() then QUEUE.resetVersion() end
  end

  -- The lobby changed hands: the party ends for everyone. Every machine keeps the queue and where it was, and a new
  -- owner with Holo is offered "Continue party".
  U.on("net.owner", function(owner, isHost)
    local had = role ~= "none" or hostParty
    if had then
      resume = {snap = QUEUE.snapshot(), time = curPos(), rate = hs and hs.r or 1}
      if role ~= "none" then endLocal() end
      toast("The host left; the watch party ended", "warn")
    end
    resetPeerSide()
    if had and isHost then
      U.emit("party.continuePrompt", PARTY.hostName())
    elseif not isHost then
      resume = nil
    end
    U.emit("party.changed")
  end)

  U.on("net.leave", function()
    if role ~= "none" then endLocal() end
    resetPeerSide()
    resume = nil
    U.emit("party.changed")
  end)

  U.on("net.enter", function()
    -- A solo party ends when this machine joins someone else's lobby; a lobby it owns keeps it.
    if role == "host" and not NET.isHost() then
      endLocal()
      toast("Your watch party ended: you joined a lobby", "info")
    end
    resetPeerSide()
  end)

  ---------------------------------------------------------------- queue and layout changes

  U.on("queue.changed", function(kind)
    if PARTY.canControl() then U.setPref("lastQueue", QUEUE.snapshot()) end
    if role ~= "host" or kind == "current" then return end   -- peers take the current item from st.i
    queueDirtyAt = queueDirtyAt or U.now()
    if ended and QUEUE.step(1) then advance() end
  end)

  -- The host removed the item that is playing: the next one at its place plays, an empty queue ends the party.
  U.on("queue.removed", function(it, index)
    if role ~= "host" or it.id ~= openedId then return end
    local items = QUEUE.items()
    if #items == 0 then
      if inSession() then NET.postAll({t = "end", why = "empty"}) end
      endLocal()
      return
    end
    local nxt = items[index] or items[#items]
    playItem(nxt, 0)
  end)

  U.on("layout.size", function(w, h)
    if player and w then player:size(w, h) end
  end)

  U.on("cfg.changed", function(key, v)
    if key == "musicOff" then
      applyMusic()
    elseif key == "whoAdds" then
      broadcastCaps()
    elseif key == "volume" then
      U.setPref("volume", v)
      applyAudio()
    elseif key == "quality" then
      PARTY.setQuality(v)
    end
  end)

  ---------------------------------------------------------------- media events

  wum.events.on("melange.media", U.guard("party.media", function(ev)
    if role == "none" or not player then return end
    local ty = ev.type
    if ty == "loaded" then
      loaded = true
      local it = QUEUE.find(openedId)
      local d = U.num(ev.duration)
      if it and d and d > 0 then it.duration = d end
      if role == "host" and autoplay then
        autoplay = false
        schedulePlay(curPos())
      elseif role == "peer" then
        sendHost{t = "buf", b = false, i = openedId, p = curPos(), ok = true}
        if hs and hs.i == openedId then player:follow(hs, NET.hostId()) end
      end
    elseif ty == "buffering" then
      if role == "peer" then sendHost{t = "buf", b = ev.on == true, i = openedId, p = curPos(), ok = true} end
    elseif ty == "ended" then
      if ev.reason == "eof" then
        if role == "host" then advance() end
      elseif ev.reason == "error" then
        if role == "host" then
          toast("Can't play this item; skipping it", "error")
          errorAt = U.now()
        else
          sendHost{t = "buf", b = false, i = openedId, p = curPos(), ok = false}
        end
      end
    elseif ty == "error" then
      if role == "peer" then
        toast("Can't play this here", "error")
        sendHost{t = "buf", b = false, i = openedId, p = curPos(), ok = false}
      else
        toast("Can't play this item; skipping it", "error")
        errorAt = U.now()
      end
    elseif ty == "helper" and ev.state == "dead" then
      toast("The video player stopped working", "error")
    end
    U.emit("party.changed")
  end))

  ---------------------------------------------------------------- setup panel state, peers list, pack

  function PARTY.setupOpen() return setupOpen end
  function PARTY.setSetup(open)
    setupOpen = open == true
    U.emit("party.changed")
  end
  function PARTY.toggleSetup() PARTY.setSetup(not setupOpen) end

  -- The other members: {{id, name, state = "ready"|"buffering"|"nopack"|"noholo"|"error", drift}}.
  function PARTY.peers()
    local out = {}
    for _, m in ipairs(NET.members()) do
      if not m.me then
        local mi = info[m.id] or {}
        local state = "ready"
        if not m.holo then state = "noholo"
        elseif m.pack and m.pack ~= "ready" then state = "nopack"
        elseif mi.err then state = "error"
        elseif mi.buf then state = "buffering" end
        out[#out + 1] = {id = m.id, name = m.name, state = state, host = m.host, rtt = m.rtt}
      end
    end
    return out
  end

  function PARTY.pack() return wum.media.pack() end

  -- Call it from the click handler of the consent button: the click is the consent (2 s window).
  function PARTY.installPack()
    local ok, why = wum.media.install()
    if not ok and why ~= "ready" then
      local text = {gesture = "Click Download again", blocked = "Downloads are turned off in Melange.ini",
        ["unsupported-os"] = "The media pack needs 64-bit Windows", disabled = "Media is turned off in Melange.ini",
        busy = "The download is already running"}
      toast(text[why] or ("Could not start the download (" .. tostring(why) .. ")"), "error")
    end
    return ok, why
  end

  function PARTY.consentText()
    local pk = wum.media.pack() or {}
    return string.format("Holo plays videos with Melange's media pack: a %d MB download (%d MB on disk) from "
      .. "Melange's GitHub releases (github.com/JaminB/melange), installed once into Documents\\Melange\\media and "
      .. "checked against hashes built into Melange. YouTube items use yt-dlp; torrent items share your IP address "
      .. "with the swarm.", math.floor(U.num(pk.downloadMB) or 95), math.floor(U.num(pk.diskMB) or 300))
  end

  ---------------------------------------------------------------- tick

  local lastPackPoll = -1e9

  local function computePhase()
    if role == "none" then return setupOpen and "setup" or "idle" end
    if needsPack then return "needs-pack" end
    if ended then return "ended-item" end
    if not player or not pstate then return "loading" end
    if pstate.eof then return "ended-item" end
    if not loaded and not (U.num(pstate.duration) and pstate.duration > 0) then return "loading" end
    if pstate.buffering then return "buffering" end
    if pendingPlayAt then return "loading" end
    if pstate.paused then return "paused" end
    return "playing"
  end

  -- The phase is computed on read, so it is right straight after a call such as stop(); the tick emits changes.
  function PARTY.phase() return computePhase() end

  function PARTY.tick()
    local now = U.now()
    if player then
      local ok, st = pcall(player.state, player)
      pstate = ok and st or nil
    else
      pstate = nil
    end

    if role == "host" then
      if pendingPlayAt and now >= pendingPlayAt then
        pendingPlayAt = nil
        if player then player:play() end
      end
      if wantOpen and not player then
        local it = QUEUE.find(wantOpen)
        if it and openItem(it, hs and hs.p or 0, true) then wantOpen = nil end
      end
      if errorAt and now - errorAt >= 2000 then
        errorAt = nil
        advance()
      end
      if scrubAt and now - scrubAt >= SCRUB_HOLD then scrubAt = nil end
      if hs and hs.s == "play" and not pendingPlayAt and loaded and not scrubAt and now - lastBeat >= HEARTBEAT then
        lastBeat = now
        hs.p, hs.a = curPos(), now
        broadcastState(false)
      end
      if queueDirtyAt and now - queueDirtyAt >= 300 then
        queueDirtyAt = nil
        if inSession() then sendQueue() end
        presence()
      end
    elseif inSession() and not NET.isHost() then
      local host = NET.hostId()
      if not acked and now - lastHi >= HI_EVERY and NET.reachable(host) then
        lastHi = now
        NET.send(host, {t = "hi", v = 1, pack = NET.myPresence().pack or "missing", holo = VERSION})
      end
      for n, p in pairs(pendingAdds) do
        if now - p.at >= ADD_WAIT then
          pendingAdds[n] = nil
          U.emit("party.addResult", false, "no-answer")
        end
      end
      if role == "peer" then
        if needsPack and now - lastPackPoll >= 500 then
          lastPackPoll = now
          if packReady() then
            needsPack = false
            applySt()
          end
        end
        if wantOpen and now - lastOpen >= OPEN_EVERY then
          lastOpen = now
          openWanted()
        end
      end
    end

    applyMusic()
    applyAudio()
    local ph = computePhase()
    if ph ~= phase then
      phase = ph
      U.emit("party.changed")
    end
  end

  presence()
  wum.timers.every(0, U.guard("party", PARTY.tick))
end

-- ==== src/45_queue.lua ====
-- queue (P2): the host's play queue, its wire pages, the peers' mirror of it, and the torrents its items need.
-- Items are {id, kind = "yt"|"bt", url (canonical), file (torrent file index), title, duration, live}.
-- Bus events: "queue.changed" (with "current" when only the current item changed: no new version, nothing to send),
-- "queue.pick" (token, files, name) for the torrent file picker, "queue.picked" (item), "queue.removed" (item, index).
-- A member's add is an item with `by` (display name) and `byId` (SteamID string); the host checks and appends it
-- (QUEUE.addFor), the members' own picks go to the host through PARTY.requestAdd.
do
  local MAX_ITEMS = 200
  local TITLE = 120
  local PAGE_BYTES = 7000            -- a reliable message is at most 8 KB
  local MAX_PAGES = 64
  local MAX_TORRENTS = 3             -- the core allows 4 per mod; one stays free for a new magnet's file list
  local MEMBER_MAX = 50              -- items one member may have in the queue at a time
  local HOST_WAIT = 40000            -- host: a member's magnet gets its file list within this (the member waits 45 s)
  local HOST_WAITS = 2               -- host: members' magnets waiting for a file list at once (one torrent slot stays)
  QUEUE.MEMBER_MAX = MEMBER_MAX

  local items, cur, qv, nextId = {}, nil, 0, 1
  local picks, nextToken = {}, 1
  local torrents = {}                -- canonical magnet -> {t = handle, files = list|nil, waiting = {fn...}}
  local partial = nil                -- the peer's pages being assembled: {qv, pages, got = {page -> items}, n, cur}
  local hostWaits = {}               -- host: magnet url -> {at, fns} while members' adds wait for the file list

  local function changed()
    qv = qv + 1
    U.emit("queue.changed")
  end

  function QUEUE.items() return items end
  function QUEUE.version() return qv end
  function QUEUE.count() return #items end

  function QUEUE.indexOf(id)
    for i, it in ipairs(items) do
      if it.id == id then return i end
    end
  end

  function QUEUE.find(id)
    local i = QUEUE.indexOf(id)
    return i and items[i]
  end

  -- The number of items added by the member with this SteamID string.
  function QUEUE.countBy(id)
    local n = 0
    if id == nil then return 0 end
    for _, it in ipairs(items) do
      if it.byId == id then n = n + 1 end
    end
    return n
  end

  -- True if an item has this url and file (file is nil for a YouTube item).
  function QUEUE.has(url, file)
    for _, it in ipairs(items) do
      if it.url == url and it.file == file then return true end
    end
    return false
  end

  function QUEUE.current() return cur and QUEUE.find(cur) or nil end
  function QUEUE.currentIndex() return cur and QUEUE.indexOf(cur) or nil end

  -- Sets the current item. It is not a new queue version: the peers follow the host's st.i, so a new item never
  -- resends the whole queue.
  function QUEUE.setCurrent(id)
    if id ~= nil and not QUEUE.find(id) then return false end
    if cur ~= id then
      cur = id
      U.emit("queue.changed", "current")
    end
    return true
  end

  -- The item delta steps from the current one (1 = next, -1 = previous), or nil past either end. Without a current
  -- item, next is the first.
  function QUEUE.step(delta)
    local i = QUEUE.currentIndex()
    if not i then return delta > 0 and items[1] or nil end
    return items[i + delta]
  end

  local function canEdit()
    if not PARTY.canControl() then return false end
    return true
  end

  local function append(it)
    if #items >= MAX_ITEMS then return nil, "full" end
    it.id = nextId
    nextId = nextId + 1
    items[#items + 1] = it
    return it
  end

  ---------------------------------------------------------------- torrents

  local function countTorrents()
    local n = 0
    for _ in pairs(torrents) do n = n + 1 end
    return n
  end

  local function openTorrent(url)
    local e = torrents[url]
    if e and not e.closed then return e end
    if countTorrents() >= MAX_TORRENTS then QUEUE.keepTorrents(PARTY.currentUrl()) end
    e = {waiting = {}}
    local t, why = wum.media.torrent(url, U.guard("queue.torrent", function(res)
      if type(res) ~= "table" then return end
      if type(res.files) == "table" then e.files, e.name = res.files, res.name end
      if res.error then e.error = tostring(res.error) end
      local w = e.waiting
      e.waiting = {}
      for _, fn in ipairs(w) do fn(e) end
    end))
    if not t then return nil, why end
    e.t = t
    torrents[url] = e
    return e
  end

  -- The open torrent for a magnet (opened if needed): entry {t, files, name, error}, or nil, reason.
  function QUEUE.torrentFor(url) return openTorrent(url) end

  function QUEUE.closeTorrent(url)
    local e = torrents[url]
    if not e then return end
    torrents[url] = nil
    e.closed = true
    if e.t then pcall(e.t.close, e.t) end
  end

  -- Closes every torrent except the one of `keepUrl` and those still waiting for a file pick.
  function QUEUE.keepTorrents(keepUrl)
    local busy = {}
    for _, p in pairs(picks) do busy[p.url] = true end
    for url in pairs(hostWaits) do busy[url] = true end
    for url in pairs(torrents) do
      if url ~= keepUrl and not busy[url] then QUEUE.closeTorrent(url) end
    end
  end

  function QUEUE.closeAllTorrents()
    for token in pairs(picks) do picks[token] = nil end
    for url in pairs(hostWaits) do hostWaits[url] = nil end
    for url in pairs(torrents) do QUEUE.closeTorrent(url) end
  end

  -- The video files of a torrent, largest first (the picker lists nothing else, design S3).
  function QUEUE.videoFiles(files)
    local out = {}
    for _, f in ipairs(type(files) == "table" and files or {}) do
      if type(f) == "table" and f.video == true and math.type(f.index) == "integer" then
        out[#out + 1] = {index = f.index, path = U.trim(f.path, 240), size = U.num(f.size) or 0}
      end
    end
    table.sort(out, function(a, b)
      if a.size ~= b.size then return a.size > b.size end
      return a.index < b.index
    end)
    return out
  end

  local function baseName(path)
    local name = (tostring(path):match("([^/\\]+)$") or tostring(path)):gsub("%.%w+$", "")
    return name
  end

  -- attrib (optional): {by, byId} of the member who added it.
  local function addTorrentItem(url, file, title, attrib)
    local it, why = append{kind = "bt", url = url, file = file, title = U.trim(title, TITLE), duration = 0,
      by = attrib and attrib.by, byId = attrib and attrib.byId}
    if not it then return nil, why end
    changed()
    -- Keep the file list of the newest magnet for a quick start, but never hold more than the cap.
    if countTorrents() > MAX_TORRENTS - 1 and url ~= PARTY.currentUrl() then QUEUE.closeTorrent(url) end
    return it
  end

  function QUEUE.pickFile(token, index)
    local p = picks[token]
    if not p then return nil, "unknown" end
    for _, f in ipairs(p.files) do
      if f.index == index then
        picks[token] = nil
        if p.forHost then
          -- A member's pick: the host adds it. The local torrent was only for the file list.
          local title = baseName(f.path)
          local ok, why = PARTY.requestAdd{u = p.url, f = index, ti = title}
          if PARTY.currentUrl() ~= p.url then QUEUE.closeTorrent(p.url) end
          if ok then U.emit("party.addSent", title) end
          return ok, why
        end
        local it, why = addTorrentItem(p.url, index, baseName(f.path))
        if it then U.emit("queue.picked", it) end
        return it ~= nil, why
      end
    end
    return nil, "file"
  end

  -- Magnets still waiting for their file list, oldest first: {{name, peers, secs}}. A magnet carries no file list; it
  -- comes from peers, which can take a minute or more.
  function QUEUE.reading()
    local out = {}
    for _, p in pairs(picks) do
      if #p.files == 0 then
        local e, peers = torrents[p.url], 0
        if e and e.t then
          local ok, st = pcall(e.t.status, e.t)
          if ok and type(st) == "table" then peers = U.num(st.peers) or 0 end
        end
        out[#out + 1] = {name = p.name, peers = peers, secs = (U.now() - (p.since or U.now())) / 1000}
      end
    end
    table.sort(out, function(a, b) return a.secs > b.secs end)
    return out
  end

  -- Closes the torrent of a magnet when no item, no playing video, no open pick and no member's add needs it.
  local function releaseTorrent(url)
    local used = PARTY.currentUrl() == url or hostWaits[url] ~= nil
    for _, it in ipairs(items) do used = used or it.url == url end
    for _, p in pairs(picks) do used = used or p.url == url end
    if not used then QUEUE.closeTorrent(url) end
  end

  function QUEUE.cancelPick(token)
    local p = picks[token]
    if not p then return false end
    picks[token] = nil
    releaseTorrent(p.url)
    return true
  end

  local function onTorrentFiles(token, e)
    local p = picks[token]
    if not p then return end
    if e.error or not e.files then
      picks[token] = nil
      QUEUE.closeTorrent(p.url)
      U.emit("party.toast", e.error == "helper" and "The video player could not start (see Melange.log)" or
        "This torrent could not be read", "error")
      return
    end
    local vids = QUEUE.videoFiles(e.files)
    if #vids == 0 then
      picks[token] = nil
      QUEUE.closeTorrent(p.url)
      U.emit("party.toast", "No video file in this torrent", "warn")
      return
    end
    p.files, p.name = vids, U.trim(e.name or p.name, TITLE)
    if #vids == 1 then
      QUEUE.pickFile(token, vids[1].index)
    else
      U.emit("queue.pick", token, vids, p.name)
    end
  end

  ---------------------------------------------------------------- adding

  local function fillTitle(url, res)
    if type(res) ~= "table" or type(res.items) ~= "table" or type(res.items[1]) ~= "table" then return end
    local r = res.items[1]
    for _, it in ipairs(items) do
      if it.url == url and it.untitled then
        it.untitled = nil
        it.title = U.trim(r.title, TITLE)
        if it.title == "" then it.title = "YouTube video" end
        it.duration = U.num(r.duration) and math.max(0, r.duration) or 0
        changed()
      end
    end
  end

  -- True once Melange has installed yt-dlp, which every YouTube link needs (it arrives a moment after the pack).
  function QUEUE.haveYtdlp()
    local ok, pk = pcall(wum.media.pack)
    return ok and type(pk) == "table" and type(pk.ytdlp) == "string" and pk.ytdlp ~= ""
  end

  local PLAYLIST_MSG = {
    private = "That playlist is private",
    ytdlp = "YouTube needs yt-dlp, which Melange has not downloaded yet; try again soon",
    playlist = "Could not list that playlist",
  }

  -- The result of wum.media.resolve for a playlist. The host's own add (no attrib) toasts; a member's add (attrib =
  -- {by, byId}) adds at most `room` items and reports through done(ok, why, count) instead.
  local function addPlaylist(res, attrib, room, done)
    local function fail(why)
      if done then done(false, why, 0) else U.emit("party.toast", PLAYLIST_MSG[why], "error") end
    end
    if type(res) ~= "table" then return fail("playlist") end
    if res.error then
      if res.error == "private" then return fail("private") end
      return fail(QUEUE.haveYtdlp() and "playlist" or "ytdlp")
    end
    if attrib then room = math.min(room or MEMBER_MAX, MEMBER_MAX - QUEUE.countBy(attrib.byId)) end
    local n, limit = 0, nil
    for _, r in ipairs(type(res.items) == "table" and res.items or {}) do
      local c = type(r) == "table" and type(r.url) == "string" and wum.media.classify(r.url)
      if c and c.kind == "youtube" and c.id then
        if room and n >= room then
          limit = "member-full"
          break
        end
        local it = append{kind = "yt", url = c.url, title = U.trim(r.title, TITLE),
          duration = U.num(r.duration) and math.max(0, r.duration) or 0, live = c.live or nil,
          by = attrib and attrib.by, byId = attrib and attrib.byId}
        if not it then
          limit = "full"
          break
        end
        if it.title == "" then it.title = "YouTube video" end
        n = n + 1
      end
    end
    if n > 0 then changed() end
    if done then
      done(n > 0, n == 0 and (limit or "playlist") or limit, n)
    else
      U.emit("party.toast", n > 0 and ("Added " .. n .. " videos") or "That playlist has no playable videos",
        n > 0 and "info" or "warn")
    end
  end

  local function packReady()
    local ok, pk = pcall(wum.media.pack)
    return ok and type(pk) == "table" and pk.state == "ready"
  end

  -- Host: adds a classified link for a member (bypasses canEdit, never the checks). attrib = {by, byId, f, ti}.
  -- done(ok, why, count, title) is called exactly once (possibly later: playlist, title-less torrent).
  function QUEUE.addFor(c, attrib, done)
    local by, byId = attrib.by, attrib.byId
    local mine = {by = by, byId = byId}
    local isMagnet = c.kind == "magnet"
    local f = isMagnet and math.type(attrib.f) == "integer" and attrib.f >= 0 and attrib.f <= 100000 and attrib.f or nil
    if #items >= MAX_ITEMS then return done(false, "full") end
    if QUEUE.has(c.url, f) then return done(false, "dup") end
    local room = MEMBER_MAX - QUEUE.countBy(byId)
    if room <= 0 then return done(false, "member-full") end
    if isMagnet then
      if f then
        local title = U.trim(attrib.ti, TITLE)
        if title == "" then title = c.name or "Torrent" end
        local it, why = addTorrentItem(c.url, f, title, mine)
        if not it then return done(false, why) end
        return done(true, nil, 1, it.title)
      end
      -- No file chosen (the member has no media pack): the host reads the file list and takes the largest video.
      -- Members' magnets never hold every torrent slot, and give up after HOST_WAIT (a dead magnet would else keep
      -- its slot for the whole party).
      local url = c.url
      if not hostWaits[url] then
        local n = 0
        for _ in pairs(hostWaits) do n = n + 1 end
        if n >= HOST_WAITS then return done(false, "host-busy") end
      end
      local e, why = openTorrent(url)
      if not e then return done(false, why) end
      local answered = false
      local function filesIn(x)
        if answered then return end
        answered = true
        local w = hostWaits[url]
        if w then
          for i = #w.fns, 1, -1 do if w.fns[i] == filesIn then table.remove(w.fns, i) end end
          if #w.fns == 0 then hostWaits[url] = nil end
        end
        local function refuse(reason)
          releaseTorrent(url)
          return done(false, reason)
        end
        if x.error then return refuse(x.error == "slow" and "torrent-slow" or "torrent") end
        local vids = QUEUE.videoFiles(x.files)
        if #vids == 0 then return refuse("no-video") end
        if QUEUE.has(url, vids[1].index) then return refuse("dup") end
        if MEMBER_MAX - QUEUE.countBy(byId) <= 0 then return refuse("member-full") end
        local it, why2 = addTorrentItem(url, vids[1].index, baseName(vids[1].path), mine)
        if not it then return refuse(why2) end
        return done(true, nil, 1, it.title)
      end
      if e.files or e.error then
        filesIn(e)
      else
        local w = hostWaits[url] or {at = U.now(), fns = {}}
        hostWaits[url] = w
        w.fns[#w.fns + 1] = filesIn
        e.waiting[#e.waiting + 1] = U.guard("queue.addFor", filesIn)
      end
      return
    end
    if c.id then
      local it = append{kind = "yt", url = c.url, title = "YouTube video", duration = 0, untitled = true,
        live = c.live or nil, by = by, byId = byId}
      changed()
      local url = it.url
      wum.media.resolve(url, U.guard("queue.title", function(res) fillTitle(url, res) end))
      return done(true, nil, 1, "YouTube video")
    end
    local id, why = wum.media.resolve(c.url, U.guard("queue.playlist", function(res)
      addPlaylist(res, mine, room, done)
    end))
    if not id then return done(false, why) end
  end

  -- A member's add: a YouTube link or a magnet link goes to the host (PARTY.requestAdd). A magnet is first read
  -- locally when the media pack is ready, so the member picks the file; otherwise the host picks the largest video.
  local function addAsMember(c)
    if #items >= MAX_ITEMS then return nil, "full" end
    if QUEUE.countBy(NET.me()) >= MEMBER_MAX then return nil, "member-full" end
    if c.kind == "youtube" and c.id and QUEUE.has(c.url, nil) then return nil, "dup" end
    if c.kind == "magnet" and packReady() then
      local e = openTorrent(c.url)
      if e then
        local token = nextToken
        nextToken = nextToken + 1
        picks[token] = {url = c.url, name = c.name or "Torrent", files = {}, since = U.now(), forHost = true}
        if e.files or e.error then
          onTorrentFiles(token, e)
        else
          e.waiting[#e.waiting + 1] = function(x) onTorrentFiles(token, x) end
        end
        return true
      end
    end
    return PARTY.requestAdd{u = c.url}
  end

  -- Adds what the user typed or pasted: true (a playlist or a torrent finishes later), or nil and a reason:
  -- "unsupported-url", "not-host", "full", or a wum.media reason ("busy", "first-use-in-match", ...). A member
  -- (PARTY.canAdd) gets true, "sent" when the request went to the host, or the PARTY.addWhyNot reason.
  function QUEUE.add(text)
    if type(text) ~= "string" then return nil, "unsupported-url" end
    local c = wum.media.classify(text)
    if not c then return nil, "unsupported-url" end
    if not canEdit() then
      if not PARTY.canAdd() then return nil, PARTY.addWhyNot() or "not-host" end
      return addAsMember(c)
    end
    if #items >= MAX_ITEMS then return nil, "full" end
    if c.kind == "magnet" then
      local e, why = openTorrent(c.url)
      if not e then return nil, why end
      local token = nextToken
      nextToken = nextToken + 1
      picks[token] = {url = c.url, name = c.name or "Torrent", files = {}, since = U.now()}
      if e.files or e.error then
        onTorrentFiles(token, e)
      else
        e.waiting[#e.waiting + 1] = function(x) onTorrentFiles(token, x) end
      end
      return true
    end
    if c.id then
      local it = append{kind = "yt", url = c.url, title = "YouTube video", duration = 0, untitled = true,
        live = c.live or nil}
      changed()
      local url = it.url
      wum.media.resolve(url, U.guard("queue.title", function(res) fillTitle(url, res) end))
      return true
    end
    local id, why = wum.media.resolve(c.url, U.guard("queue.playlist", function(res) addPlaylist(res) end))
    if not id then return nil, why end
    return true
  end

  local function removeAt(i)
    local it = table.remove(items, i)
    local id = it.id
    if cur == id then cur = nil end
    if it.kind == "bt" then
      local used = false
      for _, x in ipairs(items) do used = used or x.url == it.url end
      if not used and PARTY.currentUrl() ~= it.url then QUEUE.closeTorrent(it.url) end
    end
    U.emit("queue.removed", it, i)
    changed()
    return true
  end

  function QUEUE.remove(id)
    if not canEdit() then return nil, "not-host" end
    local i = QUEUE.indexOf(id)
    if not i then return nil, "unknown" end
    return removeAt(i)
  end

  -- Host: removes an item for the member who added it (byId is the member's SteamID string); nothing else.
  function QUEUE.removeFor(id, byId)
    local i = QUEUE.indexOf(id)
    if not i then return nil, "unknown" end
    if byId == nil or items[i].byId ~= byId then return nil, "not-yours" end
    return removeAt(i)
  end

  function QUEUE.move(id, delta)
    if not canEdit() then return nil, "not-host" end
    local i = QUEUE.indexOf(id)
    if not i then return nil, "unknown" end
    local j = U.clamp(i + delta, 1, #items)
    if j == i then return false end
    local it = table.remove(items, i)
    table.insert(items, j, it)
    changed()
    return true
  end

  function QUEUE.clear()
    items, cur = {}, nil
    changed()
  end

  ---------------------------------------------------------------- snapshots (resume) and wire pages

  function QUEUE.snapshot() return {items = U.copy(items), cur = cur} end

  -- Loads a snapshot as this machine's own queue (a new host continuing, or the stored last queue). Items are
  -- checked again like wire items and get new ids; returns the new id of the snapshot's current item.
  function QUEUE.load(snap)
    items, cur = {}, nil
    local newCur
    for _, it in ipairs(type(snap) == "table" and type(snap.items) == "table" and snap.items or {}) do
      local w = QUEUE.checkWire({id = 1, k = it.kind, u = it.url, f = it.file, ti = it.title, d = it.duration,
        b = it.by, bi = it.byId})
      if w then
        local n = append(w)
        if not n then break end
        if it.id == snap.cur then newCur = n.id end
      end
    end
    cur = newCur
    changed()
    return newCur
  end

  local function toWire(it)
    return {id = it.id, k = it.kind, u = it.url, f = it.file, ti = it.title, d = it.duration, b = it.by,
      bi = it.byId}
  end

  -- The queue as "q" messages: {{t = "q", qv, page, pages, items, cur}, ...}, each under PAGE_BYTES. An empty queue
  -- is one page with no items.
  function QUEUE.pages()
    local pages, page, bytes = {}, {}, 0
    for _, it in ipairs(items) do
      local w = toWire(it)
      local b = NET.sizeOf(w)
      if #page > 0 and (bytes + b > PAGE_BYTES or #page >= 100) then
        pages[#pages + 1] = page
        page, bytes = {}, 0
      end
      page[#page + 1] = w
      bytes = bytes + b
    end
    pages[#pages + 1] = page
    local out = {}
    for i, p in ipairs(pages) do
      out[i] = {t = "q", qv = qv, page = i, pages = #pages, items = p, cur = cur}
    end
    return out
  end

  -- One wire item, checked: the url is classified again and must match the kind, the title is trimmed, a torrent
  -- item needs a file index. Returns a queue item (without an id) or nil.
  function QUEUE.checkWire(w)
    if type(w) ~= "table" or math.type(w.id) ~= "integer" or w.id < 1 then return nil end
    if type(w.u) ~= "string" or #w.u > 4096 then return nil end
    local c = wum.media.classify(w.u)
    if not c then return nil end
    local it = {kind = w.k, url = c.url, title = U.trim(w.ti, TITLE), duration = 0}
    local d = U.num(w.d)
    if d and d > 0 then it.duration = math.min(d, 1e7) end
    if w.k == "yt" then
      if c.kind ~= "youtube" or not c.id then return nil end
      it.live = c.live or nil
    elseif w.k == "bt" then
      if c.kind ~= "magnet" or math.type(w.f) ~= "integer" or w.f < 0 or w.f > 100000 then return nil end
      it.file = w.f
    else
      return nil
    end
    if it.title == "" then it.title = it.kind == "bt" and "Torrent" or "YouTube video" end
    -- Who added it (members' adds): a display name and a SteamID string, both optional.
    local by = U.trim(w.b, 32)
    if by ~= "" then it.by = by end
    if type(w.bi) == "string" and w.bi ~= "" and #w.bi <= 32 then it.byId = w.bi end
    return it
  end

  -- A "q" page from the host (the peer's mirror). Returns true once every page of that version arrived and the
  -- mirror was replaced, false while pages are missing, nil for a malformed or stale page.
  function QUEUE.acceptPage(m)
    local v, page, pages = m.qv, m.page, m.pages
    if math.type(v) ~= "integer" or math.type(page) ~= "integer" or math.type(pages) ~= "integer" then return nil end
    if pages < 1 or pages > MAX_PAGES or page < 1 or page > pages or type(m.items) ~= "table" then return nil end
    if v == qv and not partial then return nil end      -- already have it
    if not partial or partial.qv ~= v or partial.pages ~= pages then
      partial = {qv = v, pages = pages, got = {}, n = 0}
    end
    if not partial.got[page] then
      local list = {}
      for _, w in ipairs(m.items) do
        local it = QUEUE.checkWire(w)
        if it then
          it.id = w.id
          list[#list + 1] = it
        end
        if #list >= MAX_ITEMS then break end
      end
      partial.got[page], partial.n = list, partial.n + 1
    end
    if page == pages or math.type(m.cur) == "integer" then partial.cur = m.cur end
    if partial.n < pages then return false end
    local new, seen = {}, {}
    for p = 1, pages do
      for _, it in ipairs(partial.got[p]) do
        if #new < MAX_ITEMS and not seen[it.id] then
          seen[it.id] = true
          new[#new + 1] = it
        end
      end
    end
    items, qv = new, v
    cur = (math.type(partial.cur) == "integer" and seen[partial.cur]) and partial.cur or nil
    partial = nil
    U.emit("queue.changed")
    return true
  end

  -- The peer side: forget the host's version so the next host's pages are taken whatever their number.
  function QUEUE.resetVersion()
    partial = nil
    qv = -1
  end

  -- Sets a mirrored item's file (the host's "bt" message).
  function QUEUE.setFile(id, file)
    local it = QUEUE.find(id)
    if not it or it.kind ~= "bt" or math.type(file) ~= "integer" or file < 0 then return false end
    if it.file ~= file then
      it.file = file
      U.emit("queue.changed")
    end
    return true
  end

  -- Host: members' magnets whose file list did not come in time are refused ("torrent-slow") and their torrent closed.
  wum.timers.every(1, U.guard("queue.waits", function()
    local now, late = U.now(), {}
    for url, w in pairs(hostWaits) do
      if now - w.at >= HOST_WAIT then late[#late + 1] = url end
    end
    for _, url in ipairs(late) do
      local w = hostWaits[url]
      hostWaits[url] = nil
      for _, fn in ipairs(w.fns) do fn({error = "slow"}) end
    end
  end))
end

-- ==== src/46_spotify.lua ====
-- spotify (Holo 1.1): the adapter over Melange 0.13's wum.spotify. Nothing else in Holo indexes wum.spotify, and
-- every call goes through pcall, so on an older Melange (no wum.spotify) the music lane still relays and shows what
-- the party plays. Sign-in, tokens and the Web API are Melange's: Holo only sees the status, the library and the
-- request results. Playback is on the user's own Spotify device (Spotify Connect; Premium).
-- Bus event: "spot.status" when the cached status changed.
do
  SPOT.NEEDS = "0.13.0"
  local MAX_INFLIGHT = 4             -- Holo's own cap on waiting requests (Melange allows 8 per mod)
  local LIB_INFLIGHT = 2             -- library pages may hold at most this many, so play / pause / seek always fit
  local STALE = 30000                -- ms after which a request that never answered stops counting (Melange: 15 s)
  local LIMIT = 50

  SPOT.WHY = {
    gesture = "Click Link Spotify again",
    ["no-client-id"] = "Add your Spotify app's Client ID to Melange.ini ([Spotify] ClientId); see Holo's README",
    disabled = "Spotify is turned off in Melange.ini",
    unavailable = "Melange's Spotify module did not start; see Melange's log",
    busy = "A Spotify sign-in is already open in your browser",
    ["port-busy"] = "Melange's Spotify sign-in port is in use: change [Spotify] RedirectPort and your app's Redirect URI",
    browser = "Could not open your browser",
    premium = "Playing needs Spotify Premium",
    ["no-device"] = "Open Spotify on this PC or your phone, then try again",
    rate = "Spotify asks to slow down; trying again soon",
    auth = "Spotify is not linked",
    ["old-melange"] = "Spotify music needs Melange 0.13.0 or later",
    invalid = "Spotify refused that request",
    restricted = "Your Spotify device refused that",
    ["not-found"] = "Spotify does not let apps read this playlist",
    ["bad-request"] = "Spotify refused that request",
    network = "Could not reach Spotify (network)",
    timeout = "Spotify did not answer in time",
    server = "Spotify had a problem; try again soon",
    ["bad-response"] = "Spotify sent an answer Holo could not read",
    denied = "You did not allow access",
    ["invalid-client"] = "Check [Spotify] ClientId and the app's Redirect URI",
    exchange = "The Spotify sign-in failed; try again",
    revoked = "Spotify signed Holo out; link again",
  }

  local STATES = {disconnected = true, connecting = true, connected = true, error = true}
  local status = {state = "unavailable"}
  local statusSig = "unavailable"
  local pending, npending = {}, 0    -- token -> sent at (U.now())
  local lat = 400                    -- EWMA of half the round trip, ms

  local function noop() end

  function SPOT.has() return wum.spotify ~= nil end

  -- true, or false and a reason: "old-melange" or one of wum.spotify.available()'s.
  function SPOT.available()
    local sp = wum.spotify
    if not sp then return false, "old-melange" end
    local ok, a, why = pcall(sp.available)
    if not ok then return false, "unavailable" end
    if a == true then return true end
    return false, type(why) == "string" and why or "unavailable"
  end

  -- Cleans a status table (wum.spotify.status() or the melange.spotify event) into {state, user, premium, linked,
  -- error, why}; state "unavailable" (why = the available() reason) when Spotify cannot be used here.
  local function clean(t)
    local ok, why = SPOT.available()
    if not ok then return {state = "unavailable", why = why, linked = false, premium = false} end
    if type(t) ~= "table" or not STATES[t.state] then return {state = "disconnected", linked = false, premium = false} end
    local out = {state = t.state, linked = t.linked == true, premium = false}
    if t.state == "connected" then
      out.user = U.trim(t.user, 40)
      out.premium = t.premium == true
      out.linked = true
    elseif t.state == "error" then
      out.error = type(t.error) == "string" and U.trim(t.error, 24) or "exchange"
    end
    return out
  end

  local function setStatus(st)
    local sig = st.state .. "|" .. tostring(st.user) .. "|" .. tostring(st.premium) .. "|" .. tostring(st.linked)
      .. "|" .. tostring(st.error) .. "|" .. tostring(st.why)
    status = st
    if sig ~= statusSig then
      statusSig = sig
      U.emit("spot.status", st)
    end
  end

  local function read()
    local sp = wum.spotify
    local t
    if sp then
      local ok, v = pcall(sp.status)
      t = ok and v or nil
    end
    setStatus(clean(t))
  end
  SPOT.refresh = read

  function SPOT.status() return status end
  function SPOT.connected() return status.state == "connected" end
  function SPOT.premium() return status.state == "connected" and status.premium == true end
  function SPOT.latency() return lat end
  function SPOT.inflight() return npending end

  -- Links Spotify for Holo. Call it ONLY from a click handler: Melange opens the sign-in page only within 2 s of a
  -- click on one of Holo's regions. true, or nil and a reason (SPOT.WHY).
  function SPOT.connect()
    local sp = wum.spotify
    if not sp then return nil, "old-melange" end
    local ok, r, why = pcall(sp.connect)
    read()
    if not ok then return nil, "unavailable" end
    if r then return true end
    return nil, type(why) == "string" and why or "unavailable"
  end

  -- Signs Melange out of Spotify (every mod). It does not stop the music.
  function SPOT.disconnect()
    local sp = wum.spotify
    if not sp then return nil, "old-melange" end
    local ok, r = pcall(sp.disconnect)
    read()
    return ok and r == true or nil
  end

  -- Calls wum.spotify[name](...) under pcall. The last argument is the callback slot (nil is fine): it is always
  -- passed, wrapped, so every request answers once and counts against the cap. Returns the request id, or nil and a
  -- reason ("old-melange", "busy" with 4 requests waiting (2 for library pages), "invalid", or Melange's).
  function SPOT.call(name, ...)
    local sp = wum.spotify
    if not sp then return nil, "old-melange" end
    local f = sp[name]
    if type(f) ~= "function" then return nil, "old-melange" end
    if npending >= MAX_INFLIGHT or (name == "library" and npending >= LIB_INFLIGHT) then return nil, "busy" end
    local args = table.pack(...)
    if args.n == 0 then args.n = 1 end
    local cb = args[args.n]
    if type(cb) ~= "function" then cb = noop end
    local token = {}
    local sent = U.now()
    args[args.n] = U.guard("spot." .. name, function(res)
      if pending[token] then
        pending[token] = nil
        npending = npending - 1
        local half = (U.now() - sent) / 2
        lat = U.clamp(lat * 0.7 + half * 0.3, 150, 1500)
      end
      if type(res) ~= "table" then res = {error = "bad-response"} end
      if res.error == "auth" then read() end
      cb(res)
    end)
    pending[token] = sent
    npending = npending + 1
    local ok, rid, why = pcall(f, table.unpack(args, 1, args.n))
    if ok and rid then return rid end
    if pending[token] then
      pending[token] = nil
      npending = npending - 1
    end
    if not ok then
      U.log("warn", "wum.spotify." .. name, rid)
      return nil, "invalid"
    end
    return nil, type(why) == "string" and why or "unavailable"
  end

  -- kind "tracks" | "playlists" | "playlist" (id = a 22-character playlist id); 50 per page.
  function SPOT.library(kind, id, offset, cb)
    return SPOT.call("library", {kind = kind, id = id, offset = math.max(0, math.floor(offset or 0)), limit = LIMIT}, cb)
  end

  function SPOT.devices(cb) return SPOT.call("devices", cb) end
  function SPOT.pause(cb) return SPOT.call("pause", cb) end
  function SPOT.seek(ms, cb) return SPOT.call("seek", math.max(0, math.floor(ms)), cb) end
  function SPOT.playback(cb) return SPOT.call("playback", cb) end

  -- The device to fall back to: the active one, else the first usable computer, else the first usable device.
  function SPOT.pickDevice(items)
    if type(items) ~= "table" then return nil end
    local computer, any
    for _, d in ipairs(items) do
      if type(d) == "table" and type(d.id) == "string" and d.id ~= "" then
        if d.active == true then return d end
        if d.restricted ~= true then
          if not computer and d.type == "Computer" then computer = d end
          any = any or d
        end
      end
    end
    return computer or any
  end

  -- Plays a track at positionMs on the remembered device (pref spotifyDevice), or the active one. "no-device" (or a
  -- remembered device that is gone) lists the devices, picks one (SPOT.pickDevice), remembers it and retries once.
  -- Returns the first request id, or nil and a reason; cb gets the final result.
  function SPOT.playTrack(uri, positionMs, cb)
    cb = cb or noop
    local pos = math.max(0, math.floor(positionMs or 0))
    local pref = U.pref("spotifyDevice")
    if type(pref) ~= "string" or pref == "" then pref = nil end
    return SPOT.call("play", {uri = uri, positionMs = pos, deviceId = pref}, function(res)
      if not (res.error == "no-device" or (res.error == "not-found" and pref)) then return cb(res) end
      if pref then U.setPref("spotifyDevice", nil) end
      local rid, why = SPOT.devices(function(d)
        if d.error then return cb(d) end
        local dev = SPOT.pickDevice(d.items)
        if not dev then return cb({error = "no-device"}) end
        U.setPref("spotifyDevice", dev.id)
        local r2, why2 = SPOT.call("play", {uri = uri, positionMs = pos + math.floor(SPOT.latency()),
          deviceId = dev.id}, cb)
        if not r2 then cb({error = why2}) end
      end)
      if not rid then cb({error = why}) end
    end)
  end

  ---------------------------------------------------------------- status: the event, and a 2 s re-read

  if wum.spotify then
    wum.events.on("melange.spotify", U.guard("spot.event", function(p)
      if type(p) == "table" and (p.type == nil or p.type == "status") then setStatus(clean(p)) end
    end))
    wum.timers.every(2, U.guard("spot.poll", function()
      read()
      local now = U.now()
      for token, at in pairs(pending) do
        if now - at > STALE then
          pending[token] = nil
          npending = npending - 1
        end
      end
    end))
  end
  read()
end

-- ==== src/47_music.lua ====
-- music (Holo 1.1): the party's Spotify music lane. Its host is the lobby owner (or this machine without a lobby),
-- with or without a video party. The host keeps the music queue and an abstract clock ms = {e, i, s, p, a} (epoch,
-- item id, "play"|"pause"|"stop", position ms, the host's U.now() at which p holds) and needs no Spotify itself.
-- Every machine that listens, the host included, follows that clock on its OWN Spotify device (SPOT); the others see
-- what plays. Hiding or minimising the player, closing the panel, a video ending or a video party ending never stop
-- the music: only Stop, the end of the music queue, leaving the lobby or the lobby changing hands do (nothing here
-- listens to PARTY's end, LAYOUT or the setup panel).
-- Wire (all ignored by Holo 1.0.x): "mq" queue pages and "ms" state (host -> all), "madd" / "mrm" / "mneed"
-- (member -> host), "maddr" (host -> member). Bus events: "music.changed", "music.addResult" (ok, why, count),
-- "music.detached" (the user took over in Spotify; offer "Follow again").
do
  local MAX_ITEMS, MEMBER_MAX = 200, 50
  local TITLE, ARTISTS, BY = 80, 80, 32
  local MAX_DUR, MIN_DUR = 7200000, 1000
  local PAGE_BYTES, MAX_PAGES = 7000, 64
  local ADD_CHUNK = 20
  local HEARTBEAT = 5000             -- host: unreliable "ms" while playing
  local MQ_DEBOUNCE = 300
  local MADD_ACCEPT, MRM_ACCEPT, MNEED_ACCEPT = 500, 500, 5000   -- host, per member
  local ADD_TOAST_EVERY = 3000
  local NEED_EVERY = 3000            -- peer: "mneed" at most this often
  local ADD_EVERY = 1000             -- peer: one MUSIC.add per second
  local CHUNK_EVERY = 600            -- peer: one "madd" chunk per 0.6 s (the host takes one per 0.5 s)
  local ADD_WAIT = 45000
  local POLL_PLAY, POLL_PAUSE = 3000, 10000
  local DRIFT_MAX, SEEK_HOLD = 1500, 8000
  local OVERRIDE_GRACE = 4000        -- ms after Holo's own action before a different playback counts as the user's
  local END_SLACK = 250
  local RESUME_AFTER = 1000          -- host: the video must be off this long before auto-paused music resumes
  local PLAY_TRIES = 3               -- follower: plays of one song that failed for a passing reason, then it waits
  local PAUSE_RETRY, PAUSE_GIVEUP = 1500, 15000   -- follower: a pause that did not go through is sent again
  -- Request errors that pass: the request is worth sending again later ("busy" also when Holo's own cap is full).
  local PASSING = {busy = true, rate = true, network = true, timeout = true, server = true}
  MUSIC.MAX_ITEMS, MUSIC.MEMBER_MAX, MUSIC.ADD_CHUNK = MAX_ITEMS, MEMBER_MAX, ADD_CHUNK

  local items, mv, nextId = {}, 0, 1
  local partial = nil
  local epoch = 0
  local ms = {e = 0, i = 0, s = "stop", p = 0, a = U.now()}
  local dirtyAt, lastBeat = nil, -1e9
  local members = {}                 -- host: id -> {addAt, rmAt, needAt, toastAt}
  local autoPaused, override, vidWas, vidOffAt = false, nil, false, nil
  -- peer
  local lastNeed, lastAdd = -1e9, -1e9
  local pendingAdds, nextAddN, chunks, lastChunk = {}, 1, {}, -1e9
  -- follower
  local owned = nil                  -- {uri, e, at, playing}: the track Holo started on this machine's device
  local issued = nil                 -- {e, uri}: the state Holo last acted on (no retry within one epoch)
  local lastPb, lastPoll, polling = nil, -1e9, false
  local lastSeek, lastAction = -1e9, -1e9
  local detached, notPremium, lastError, backoffUntil = false, false, nil, -1e9
  local playTry = nil                -- {e, uri, n, at}: the last play failed for a passing reason; again at `at`
  local wantPause = nil              -- {since, next}: a pause of Holo's track that has not gone through yet
  local wasFollow = false

  local function toast(text, kind) U.emit("party.toast", text, kind or "info") end
  local function changed() U.emit("music.changed") end

  ---------------------------------------------------------------- reads

  function MUSIC.items() return items end
  function MUSIC.count() return #items end
  function MUSIC.version() return mv end
  function MUSIC.state() return ms end
  function MUSIC.isHost() return NET.isHost() end

  function MUSIC.indexOf(id)
    for i, it in ipairs(items) do
      if it.id == id then return i end
    end
  end

  function MUSIC.find(id)
    local i = MUSIC.indexOf(id)
    return i and items[i]
  end

  -- The item of ms.i, or nil. Cached per (items table, version, id): the follower, the chip and the game-music check
  -- read it every frame.
  local curItems, curMv, curI, curIt = nil, nil, nil, nil
  function MUSIC.current()
    if ms.i == 0 then return nil end
    if curItems ~= items or curMv ~= mv or curI ~= ms.i then
      curItems, curMv, curI, curIt = items, mv, ms.i, MUSIC.find(ms.i)
    end
    return curIt
  end

  -- Position of a state in ms at this machine's now; hostOffset turns this machine's clock into the host's.
  function MUSIC.pos(st, hostOffset)
    if st.s == "play" then return st.p + (U.now() + (hostOffset or 0) - st.a) end
    return st.p
  end

  local function hostOffset()
    if NET.isHost() then return 0 end
    local c = NET.clock(NET.hostId())
    return c and U.num(c.offset) or 0
  end

  -- The current position in ms, inside the current item.
  function MUSIC.position()
    local it = MUSIC.current()
    local p = MUSIC.pos(ms, hostOffset())
    if it then p = math.min(p, it.durationMs) end
    return math.max(0, p)
  end

  ---------------------------------------------------------------- items and their wire form

  -- A Spotify track URI: "spotify:track:" and a 22-character base-62 id.
  function MUSIC.validUri(u)
    return type(u) == "string" and #u == 36 and u:match("^spotify:track:[0-9A-Za-z]+$") ~= nil
  end

  -- A checked item {uri, title, artists, durationMs} or nil.
  function MUSIC.checkItem(u, ti, ar, d)
    if not MUSIC.validUri(u) then return nil end
    if math.type(d) ~= "integer" or d < MIN_DUR or d > MAX_DUR then return nil end
    local title = U.trim(ti, TITLE)
    if title == "" then title = "Spotify track" end
    return {uri = u, title = title, artists = U.trim(ar, ARTISTS), durationMs = d}
  end

  local function toWire(it)
    return {id = it.id, u = it.uri, ti = it.title, ar = it.artists, d = it.durationMs, b = it.by, bi = it.byId}
  end

  function MUSIC.checkWire(w)
    if type(w) ~= "table" or math.type(w.id) ~= "integer" or w.id < 1 then return nil end
    local it = MUSIC.checkItem(w.u, w.ti, w.ar, w.d)
    if not it then return nil end
    it.id = w.id
    local b = U.trim(w.b, BY)
    if b ~= "" then it.by = b end
    if type(w.bi) == "string" and #w.bi > 0 and #w.bi <= 32 then it.byId = w.bi end
    return it
  end

  local function countBy(id)
    local n = 0
    for _, it in ipairs(items) do
      if it.byId == id then n = n + 1 end
    end
    return n
  end

  local function hasUri(uri)
    for _, it in ipairs(items) do
      if it.uri == uri then return true end
    end
    return false
  end

  local function queueChanged()
    mv = mv + 1
    dirtyAt = dirtyAt or U.now()
    changed()
  end

  function MUSIC.pages()
    local pages, page, bytes = {}, {}, 0
    for _, it in ipairs(items) do
      local w = toWire(it)
      local b = NET.sizeOf(w)
      if #page > 0 and (bytes + b > PAGE_BYTES or #page >= 100) then
        pages[#pages + 1] = page
        page, bytes = {}, 0
      end
      page[#page + 1] = w
      bytes = bytes + b
    end
    pages[#pages + 1] = page
    local out = {}
    for i, p in ipairs(pages) do
      out[i] = {t = "mq", mv = mv, page = i, pages = #pages, items = p, cur = ms.i}
    end
    return out
  end

  -- Peer: one "mq" page; true once a whole version arrived (the mirror is swapped), false while pages are missing,
  -- nil for a bad or stale page.
  function MUSIC.acceptPage(m)
    local v, page, pages = m.mv, m.page, m.pages
    if math.type(v) ~= "integer" or math.type(page) ~= "integer" or math.type(pages) ~= "integer" then return nil end
    if pages < 1 or pages > MAX_PAGES or page < 1 or page > pages or type(m.items) ~= "table" then return nil end
    if v == mv and not partial then return nil end
    if not partial or partial.mv ~= v or partial.pages ~= pages then
      partial = {mv = v, pages = pages, got = {}, n = 0}
    end
    if not partial.got[page] then
      local list = {}
      for _, w in ipairs(m.items) do
        local it = MUSIC.checkWire(w)
        if it then list[#list + 1] = it end
        if #list >= MAX_ITEMS then break end
      end
      partial.got[page], partial.n = list, partial.n + 1
    end
    if partial.n < pages then return false end
    local new, seen = {}, {}
    for p = 1, pages do
      for _, it in ipairs(partial.got[p]) do
        if #new < MAX_ITEMS and not seen[it.id] then
          seen[it.id] = true
          new[#new + 1] = it
        end
      end
    end
    items, mv, partial = new, v, nil
    changed()
    return true
  end

  ---------------------------------------------------------------- state messages

  local function msMsg(st) return {t = "ms", e = st.e, i = st.i, s = st.s, p = st.p, a = st.a} end

  local STATES = {play = true, pause = true, stop = true}
  function MUSIC.checkMs(m)
    if type(m) ~= "table" then return nil end
    local e, i, p, a = m.e, m.i, U.num(m.p), U.num(m.a)
    if math.type(e) ~= "integer" or e < 0 or math.type(i) ~= "integer" or i < 0 then return nil end
    if not STATES[m.s] or not p or p < 0 or p > 86400000 or not a then return nil end
    return {e = e, i = i, s = m.s, p = p, a = a}
  end

  local function newer(a, b)
    if not b then return true end
    if a.e ~= b.e then return a.e > b.e end
    return a.a >= b.a
  end

  local function sendQueue(id)
    if id then NET.drop(id, "^mq%d") else for _, p in ipairs(NET.peers()) do NET.drop(p, "^mq%d") end end
    for _, page in ipairs(MUSIC.pages()) do
      if id then NET.post(id, page, "mq" .. page.page) else NET.postAll(page, "mq" .. page.page) end
    end
  end

  local function sendAll(id)
    sendQueue(id)
    NET.post(id, msMsg(ms), "ms")
  end

  ---------------------------------------------------------------- the follower (every machine, the host too)

  local function listenPref() return U.pref("musicListen", CFG.get("musicFollow")) ~= false end

  function MUSIC.listening() return listenPref() end
  function MUSIC.detached() return detached end
  function MUSIC.notPremium() return notPremium end
  function MUSIC.lastError() return lastError end
  function MUSIC.playback() return lastPb end
  function MUSIC.owned() return owned end

  local function following()
    return SPOT.premium() and not notPremium and listenPref() and not detached and MUSIC.current() ~= nil
  end
  MUSIC.following = following

  -- True while this machine follows and its device plays the party's track (the game music then stays silent).
  function MUSIC.audible()
    if owned == nil or ms.s ~= "play" or not following() then return false end
    if lastPb and lastPb.at >= owned.at and lastPb.playing ~= true then return false end
    return true
  end

  -- Sends the pause of wantPause; a passing failure (Holo's request cap full, rate, network...) is sent again from
  -- the tick, so Stop, Mute and leaving never leave the music playing.
  local function sendPause()
    local w = wantPause
    if not w then return end
    w.next = math.huge                                           -- waiting for the answer
    local rid, why = SPOT.pause(function(res)
      if wantPause ~= w then return end
      if res.error and PASSING[res.error] then
        w.next = U.now() + (res.error == "rate" and (U.num(res.retryAfter) or 5) * 1000 or PAUSE_RETRY)
      else
        wantPause = nil
      end
    end)
    if not rid then
      if PASSING[why] then w.next = U.now() + PAUSE_RETRY else wantPause = nil end
    end
  end

  local function pauseOwned()
    if owned and owned.playing then
      owned.playing = false
      local now = U.now()
      lastAction = now
      wantPause = {since = now, next = now}
      sendPause()
    end
  end

  -- Stops following on this machine: pauses what Holo started, forgets it.
  local function release()
    pauseOwned()
    owned, issued = nil, nil
  end

  local function playNow(it)
    local target = MUSIC.pos(ms, hostOffset()) + SPOT.latency()
    if target >= it.durationMs - END_SLACK then return end      -- it is about to end: the next state plays the next
    local e, uri, now = ms.e, it.uri, U.now()
    issued = {e = e, uri = uri}
    owned = {uri = uri, e = e, at = now, playing = true}
    wantPause = nil                                               -- playing again: an older pause is moot
    lastSeek, lastAction = now, now
    local rid, why = SPOT.playTrack(uri, math.max(0, math.floor(target)), function(res)
      if not res.error then
        lastError = nil
        if playTry and playTry.e == e then playTry = nil end
        changed()
        return
      end
      if owned and owned.e == e and owned.uri == uri then owned = nil end
      if res.error == "premium" then
        notPremium = true
      elseif res.error == "rate" then
        backoffUntil = U.now() + (U.num(res.retryAfter) or 5) * 1000
      end
      -- a passing failure plays the same song again a little later (a few times), not only at the next song
      if PASSING[res.error] and issued and issued.e == e and issued.uri == uri then
        local n = (playTry and playTry.e == e and playTry.uri == uri) and playTry.n + 1 or 1
        if n <= PLAY_TRIES then
          local wait = res.error == "rate" and (U.num(res.retryAfter) or 5) * 1000 or 2000 * n
          playTry = {e = e, uri = uri, n = n, at = U.now() + wait}
          issued = nil
        end
      end
      lastError = res.error
      changed()
    end)
    if not rid then
      owned = nil
      lastError = why
      if why == "busy" then issued = nil end                     -- try again next frame
    end
  end

  -- React to the state: a new epoch plays, pauses or stops this machine's device.
  local function onState()
    if not following() then return end
    local it = MUSIC.current()
    if ms.s == "play" and it then
      if issued and issued.e == ms.e and issued.uri == it.uri then return end   -- this epoch: drift only
      if playTry and playTry.e == ms.e and playTry.uri == it.uri and U.now() < playTry.at then return end
      playNow(it)
    elseif ms.s == "pause" then
      issued = {e = ms.e}
      pauseOwned()
    else
      issued = {e = ms.e}
      release()
    end
  end

  local function setDetached()
    detached = true
    owned, issued = nil, nil
    changed()
    U.emit("music.detached")
  end

  -- Clears "detached" and plays along again (the "Follow again" action, or Listen pressed).
  function MUSIC.followAgain()
    detached, issued, lastError = false, nil, nil
    onState()
    changed()
  end

  -- Listen / Mute here: this machine plays the party's music on its Spotify, or not (off pauses what Holo started).
  function MUSIC.setListen(on)
    on = on == true
    U.setPref("musicListen", on)
    if on then
      MUSIC.followAgain()
    else
      release()
      changed()
    end
  end

  local function onPlayback(res)
    polling = false
    if res.error then
      if res.error == "rate" then backoffUntil = U.now() + (U.num(res.retryAfter) or 5) * 1000 end
      return
    end
    local at = U.num(res.at) or U.now()
    lastPb = {active = res.active == true, playing = res.playing == true, uri = res.uri, at = at,
      positionMs = U.num(res.positionMs) or 0,
      device = type(res.device) == "table" and {name = U.trim(res.device.name, 40)} or nil}
    if not following() or not owned or ms.s ~= "play" then return end
    if lastPb.at < owned.at then return end
    local now = U.now()
    if not lastPb.active then
      -- the device went away: show the device hint; the next epoch (or Listen) tries again
      owned, lastError = nil, "no-device"
      changed()
      return
    end
    local want = MUSIC.pos(ms, hostOffset())
    local it = MUSIC.current()
    -- around the end of a song the device stops (or moves on) before the host's next state arrives: not the user
    if not it or want >= it.durationMs - 5000 then return end
    if lastPb.uri ~= owned.uri or not lastPb.playing then
      if now - lastAction > OVERRIDE_GRACE then setDetached() end
      return
    end
    lastError = nil
    local drift = (lastPb.positionMs + (now - lastPb.at)) - want
    if math.abs(drift) > DRIFT_MAX and now - lastSeek > SEEK_HOLD then
      lastSeek, lastAction = now, now
      SPOT.seek(math.floor(want + SPOT.latency()))
    end
  end

  local function followTick(now)
    local f = following()
    if f ~= wasFollow then
      wasFollow = f
      if f then onState() end
    end
    if not f then return end
    if ms.s == "play" and issued == nil then onState() end
    if polling and now - lastPoll > 20000 then polling = false end   -- an answer that never came
    if polling or now < backoffUntil or ms.s == "stop" then return end
    local every = ms.s == "play" and POLL_PLAY or POLL_PAUSE
    if now - lastPoll < every then return end
    lastPoll = now
    if SPOT.playback(onPlayback) then polling = true end
  end

  ---------------------------------------------------------------- host: state changes

  local function setMs(s, i, p)
    epoch = math.max(epoch, ms.e) + 1
    local now = U.now()
    if i ~= ms.i then detached = false end
    ms = {e = epoch, i = i or 0, s = s, p = math.max(0, math.floor(p or 0)), a = now}
    lastBeat = now
    if NET.inSession() then NET.postAll(msMsg(ms), "ms") end
    onState()
    changed()
  end

  local function hostOnly()
    if not NET.isHost() then return nil, "not-host" end
    return true
  end

  local function vidNow() return PARTY.role() ~= "none" and PARTY.phase() == "playing" end

  -- Host: appends checked items {uri, title, artists, durationMs, by?, byId?}; returns how many and a reason for
  -- the ones left out ("full", "member-full", "dup").
  local function append(list, by, byId)
    local c, why = 0, nil
    for _, x in ipairs(list) do
      if #items >= MAX_ITEMS then
        why = "full"
        break
      end
      if byId and countBy(byId) >= MEMBER_MAX then
        why = "member-full"
        break
      end
      if hasUri(x.uri) then
        why = why or "dup"
      else
        items[#items + 1] = {id = nextId, uri = x.uri, title = x.title, artists = x.artists,
          durationMs = x.durationMs, by = by, byId = byId}
        nextId = nextId + 1
        c = c + 1
      end
    end
    if c > 0 then queueChanged() end
    return c, why
  end

  -- A library song {uri, name, artists, durationMs} as an item, or nil.
  local function fromLibrary(x)
    if type(x) ~= "table" then return nil end
    local d = U.num(x.durationMs)
    return MUSIC.checkItem(x.uri, x.name or x.title, x.artists, d and math.tointeger(math.floor(d)))
  end

  -- Host: adds library songs straight to the queue (no "by").
  function MUSIC.addLocal(list)
    local ok, why = hostOnly()
    if not ok then return nil, why end
    local clean = {}
    for _, x in ipairs(list) do clean[#clean + 1] = fromLibrary(x) end
    local c, w = append(clean)
    if c == 0 then return nil, w or "invalid" end
    return c, w
  end

  function MUSIC.playItem(id, posMs)
    local ok, why = hostOnly()
    if not ok then return nil, why end
    local it = MUSIC.find(id)
    if not it then return nil, "unknown" end
    autoPaused = false
    if vidNow() then override = PARTY.currentId() end
    setMs("play", it.id, U.clamp(U.num(posMs) or 0, 0, it.durationMs - 1000))
    return true
  end

  function MUSIC.toggle()
    local ok, why = hostOnly()
    if not ok then return nil, why end
    if ms.s == "play" then
      autoPaused = false
      setMs("pause", ms.i, MUSIC.position())
    elseif ms.s == "pause" and MUSIC.current() then
      autoPaused = false
      if vidNow() then override = PARTY.currentId() end
      setMs("play", ms.i, ms.p)
    else
      local it = MUSIC.current() or items[1]
      if not it then return nil, "empty" end
      return MUSIC.playItem(it.id, 0)
    end
    return true
  end

  function MUSIC.stop()
    local ok, why = hostOnly()
    if not ok then return nil, why end
    autoPaused = false
    setMs("stop", ms.i, 0)
    return true
  end

  function MUSIC.next()
    local ok, why = hostOnly()
    if not ok then return nil, why end
    local i = MUSIC.indexOf(ms.i)
    local nxt = i and items[i + 1] or (not i and items[1]) or nil
    if not nxt then
      autoPaused = false
      setMs("stop", ms.i, 0)
      toast("The music queue finished")
      return true
    end
    return MUSIC.playItem(nxt.id, 0)
  end

  function MUSIC.prev()
    local ok, why = hostOnly()
    if not ok then return nil, why end
    local i = MUSIC.indexOf(ms.i)
    if not i then return MUSIC.toggle() end
    if MUSIC.position() > 3000 or i == 1 then
      if ms.s == "stop" then return MUSIC.playItem(ms.i, 0) end
      setMs(ms.s, ms.i, 0)
      return true
    end
    return MUSIC.playItem(items[i - 1].id, 0)
  end

  function MUSIC.seek(posMs)
    local ok, why = hostOnly()
    if not ok then return nil, why end
    local it = MUSIC.current()
    posMs = U.num(posMs)
    if not it or ms.s == "stop" or not posMs then return nil, "seek" end
    setMs(ms.s, ms.i, U.clamp(posMs, 0, it.durationMs - 1000))
    return true
  end

  local function removeAt(i)
    local it = table.remove(items, i)
    queueChanged()
    if it.id == ms.i then
      local nxt = items[i]
      if nxt and ms.s ~= "stop" then
        setMs(ms.s == "pause" and "pause" or "play", nxt.id, 0)
      else
        setMs("stop", 0, 0)
      end
    end
    return true
  end

  function MUSIC.remove(id)
    local ok, why = hostOnly()
    if not ok then return nil, why end
    local i = MUSIC.indexOf(id)
    if not i then return nil, "unknown" end
    return removeAt(i)
  end

  function MUSIC.move(id, delta)
    local ok, why = hostOnly()
    if not ok then return nil, why end
    local i = MUSIC.indexOf(id)
    if not i then return nil, "unknown" end
    local j = U.clamp(i + delta, 1, #items)
    if j == i then return false end
    table.insert(items, j, table.remove(items, i))
    queueChanged()
    return true
  end

  function MUSIC.clear()
    local ok, why = hostOnly()
    if not ok then return nil, why end
    if #items == 0 then return true end
    items = {}
    queueChanged()
    if ms.s ~= "stop" or ms.i ~= 0 then setMs("stop", 0, 0) end
    return true
  end

  ---------------------------------------------------------------- members add and remove

  -- True if this machine may add songs now: it hosts the lane, or the lobby owner's Holo 1.1 accepts music adds.
  function MUSIC.canAdd()
    if NET.isHost() then return true end
    local caps = PARTY.hostCaps()
    return caps ~= nil and caps.music == true and caps.madd == true and NET.reachable(NET.hostId())
  end

  -- Why a member cannot add: "no-host" | "old-host" | "host-only" | nil.
  function MUSIC.addWhyNot()
    if MUSIC.canAdd() then return nil end
    if not NET.inSession() then return nil end
    if not NET.reachable(NET.hostId()) then return "no-host" end
    local caps = PARTY.hostCaps()
    if not caps then return PARTY.hostAcked() and "old-host" or "no-host" end
    if caps.music ~= true then return "old-host" end
    if caps.madd ~= true then return "host-only" end
    return "no-host"
  end

  -- True if the lobby owner runs a Holo without the music lane.
  function MUSIC.oldHost() return MUSIC.addWhyNot() == "old-host" end

  -- Adds library songs {uri, name, artists, durationMs}: straight to the queue on the host, else sent to the host in
  -- chunks of 20 (the answers come as "music.addResult"). Returns a count (host) or "sent", or nil and a reason.
  function MUSIC.add(list)
    if type(list) ~= "table" or #list == 0 then return nil, "invalid" end
    if NET.isHost() then return MUSIC.addLocal(list) end
    if not MUSIC.canAdd() then return nil, MUSIC.addWhyNot() or "no-host" end
    local now = U.now()
    if now - lastAdd < ADD_EVERY then return nil, "rate" end
    local wire = {}
    for _, x in ipairs(list) do
      local it = fromLibrary(x)
      if it then wire[#wire + 1] = {u = it.uri, ti = it.title, ar = it.artists, d = it.durationMs} end
    end
    if #wire == 0 then return nil, "invalid" end
    lastAdd = now
    for i = 1, #wire, ADD_CHUNK do
      local chunk = {}
      for j = i, math.min(#wire, i + ADD_CHUNK - 1) do chunk[#chunk + 1] = wire[j] end
      chunks[#chunks + 1] = chunk
    end
    return true, "sent"
  end

  -- Member: asks the host to remove a song this machine added.
  function MUSIC.requestRemove(id)
    if NET.isHost() then return MUSIC.remove(id) end
    local it = MUSIC.find(id)
    if not it or it.byId == nil or it.byId ~= NET.me() then return nil, "not-yours" end
    if not MUSIC.canAdd() then return nil, MUSIC.addWhyNot() or "no-host" end
    NET.post(NET.hostId(), {t = "mrm", id = id})
    return true
  end

  local function member(id)
    local m = members[id]
    if not m then
      m = {addAt = -1e9, rmAt = -1e9, needAt = -1e9, toastAt = -1e9}
      members[id] = m
    end
    return m
  end

  local function fromMember(from, m)
    local t = m.t
    local now = U.now()
    if t == "madd" then
      local n = m.n
      if math.type(n) ~= "integer" or n < 1 or n > 2147483647 then return end
      local function reply(ok, why, c) NET.post(from, {t = "maddr", n = n, ok = ok, why = why, c = c}) end
      local mi = member(from)
      if CFG.get("whoAdds") ~= "anyone" then return reply(false, "host-only") end
      if now - mi.addAt < MADD_ACCEPT then return reply(false, "rate") end
      mi.addAt = now
      if type(m.items) ~= "table" or #m.items < 1 then return reply(false, "invalid") end
      if #m.items > ADD_CHUNK then return reply(false, "too-many") end
      local clean, bad = {}, 0
      for k = 1, #m.items do
        local w = m.items[k]
        local it = type(w) == "table" and MUSIC.checkItem(w.u, w.ti, w.ar, w.d) or nil
        if it then clean[#clean + 1] = it else bad = bad + 1 end
      end
      if #clean == 0 then return reply(false, "invalid") end
      local name = U.trim(NET.name(from), BY)
      local c, why = append(clean, name, from)
      if c == 0 and not why and bad > 0 then why = "invalid" end
      reply(c > 0, why, c)
      if c > 0 and now - mi.toastAt >= ADD_TOAST_EVERY then
        mi.toastAt = now
        toast(name .. " added " .. (c > 1 and (c .. " songs") or U.trim(clean[1].title, 60)))
      end
    elseif t == "mrm" then
      local mi = member(from)
      if math.type(m.id) ~= "integer" or now - mi.rmAt < MRM_ACCEPT then return end
      mi.rmAt = now
      local i = MUSIC.indexOf(m.id)
      if i and items[i].byId == from then removeAt(i) end
    elseif t == "mneed" then
      local mi = member(from)
      if now - mi.needAt < MNEED_ACCEPT then return end
      mi.needAt = now
      sendAll(from)
    end
  end

  local function needQueue()
    if ms.i == 0 or MUSIC.find(ms.i) then return end
    local now = U.now()
    if now - lastNeed < NEED_EVERY then return end
    lastNeed = now
    NET.post(NET.hostId(), {t = "mneed", mv = mv})
  end

  local function fromHost(from, m)
    local t = m.t
    if t == "mq" then
      if MUSIC.acceptPage(m) then
        onState()
        needQueue()
      end
    elseif t == "ms" then
      local st = MUSIC.checkMs(m)
      if not st or not newer(st, ms) then return end
      local newItem = st.i ~= ms.i
      ms = st
      if newItem and st.e > 0 then detached = false end
      needQueue()
      onState()
      changed()
    elseif t == "maddr" then
      local p = pendingAdds[m.n]
      if not p then return end
      pendingAdds[m.n] = nil
      U.emit("music.addResult", m.ok == true, type(m.why) == "string" and U.trim(m.why, 24) or nil,
        math.type(m.c) == "integer" and m.c or nil)
    end
  end

  U.on("net.msg", function(from, m)
    if from == NET.hostId() and not NET.isHost() then
      fromHost(from, m)
    elseif NET.isHost() and NET.inSession() then
      fromMember(from, m)
    end
  end)

  -- A member said hi (Holo 1.1 sends the caps then): it gets the music queue and state if there is any.
  local function greet(id)
    if not (NET.isHost() and NET.inSession()) then return end
    if #items > 0 or ms.s ~= "stop" then sendAll(id) end
  end
  U.on("party.memberHi", greet)
  U.on("net.peer", function(id, up)
    if up and NET.isHost() then greet(id) end
  end)

  ---------------------------------------------------------------- lobby lifecycle

  local wasHost = NET.isHost()       -- whether this machine hosted the lane before the last lobby event

  -- Forgets the mirror (a member) or everything (keep = false). mv = -1 so the next host's pages are taken whatever
  -- their number.
  local function resetMirror()
    items, partial, mv = {}, nil, -1
    ms = {e = 0, i = 0, s = "stop", p = 0, a = U.now()}
    pendingAdds, chunks, members = {}, {}, {}
    lastPb, polling, autoPaused, override = nil, false, false, nil
    detached = false
  end

  -- This machine left the lobby: what Holo started on its device pauses. A host keeps its songs, stopped.
  U.on("net.leave", function()
    release()
    if wasHost then
      if ms.s ~= "stop" then setMs("stop", ms.i, 0) end
      members, chunks, pendingAdds = {}, {}, {}
    else
      resetMirror()
    end
    wasHost = true
    changed()
  end)

  U.on("net.owner", function(owner, isHost)
    if owned then
      release()
      toast("The host left; the party music stopped", "warn")
    end
    owned, issued = nil, nil
    local old, e = items, ms.e
    resetMirror()
    if isHost then
      -- the new owner adopts the songs (new ids, attribution kept), stopped; it does not play them by itself
      for _, it in ipairs(old) do
        items[#items + 1] = {id = nextId, uri = it.uri, title = it.title, artists = it.artists,
          durationMs = it.durationMs, by = it.by, byId = it.byId}
        nextId = nextId + 1
      end
      epoch = math.max(epoch, e) + 1
      ms = {e = epoch, i = 0, s = "stop", p = 0, a = U.now()}
      mv = math.max(mv, 0) + 1
    end
    wasHost = isHost == true
    changed()
  end)

  U.on("net.enter", function()
    wasHost = NET.isHost()
    if wasHost then return end
    -- a solo lane ends when this machine joins someone else's lobby
    local had = #items > 0 or ms.s ~= "stop"
    release()
    resetMirror()
    if had then toast("Your party music ended: you joined a lobby") end
    changed()
  end)

  -- The "Play the party's music on my Spotify" setting: it replaces what Listen / Mute here remembered, and acts now.
  U.on("cfg.changed", function(key, v)
    if key ~= "musicFollow" then return end
    U.setPref("musicListen", nil)
    if v == false then
      release()
      changed()
    else
      MUSIC.followAgain()
    end
  end)

  U.on("spot.status", function()
    if not SPOT.connected() then notPremium = false end
    changed()
  end)

  ---------------------------------------------------------------- tick

  local function hostTick(now)
    local it = MUSIC.current()
    -- (a) the song ended: the next one
    if ms.s == "play" and it and MUSIC.pos(ms, 0) >= it.durationMs - END_SLACK then
      MUSIC.next()
    elseif ms.s ~= "stop" and ms.i ~= 0 and not it then
      setMs("stop", 0, 0)
    end
    if NET.inSession() then
      -- (b) heartbeat
      if ms.s == "play" and now - lastBeat >= HEARTBEAT then
        lastBeat = now
        local m = msMsg(ms)
        for _, id in ipairs(NET.peers()) do NET.send(id, m, {reliable = false}) end
      end
      -- (c) the queue, debounced
      if dirtyAt and now - dirtyAt >= MQ_DEBOUNCE then
        dirtyAt = nil
        sendQueue()
      end
    else
      dirtyAt = nil
    end
    -- (d) a party video plays: pause the music (setting), resume once the video stops
    local ph = PARTY.role() ~= "none" and PARTY.phase() or "idle"
    local vid = ph == "playing" or ph == "buffering" or (vidWas and ph == "loading")
    vidWas = vid
    if CFG.get("musicDuringVideo") ~= "pause" then
      autoPaused = false
      return
    end
    if vid then
      vidOffAt = nil
      if ms.s == "play" and override ~= PARTY.currentId() then
        setMs("pause", ms.i, MUSIC.position())
        autoPaused = true
      end
    elseif autoPaused then
      vidOffAt = vidOffAt or now
      if ms.s ~= "pause" then
        autoPaused = false
      elseif now - vidOffAt >= RESUME_AFTER then
        autoPaused, vidOffAt = false, nil
        setMs("play", ms.i, ms.p)
      end
    end
  end

  local function peerTick(now)
    local host = NET.hostId()
    if chunks[1] and now - lastChunk >= CHUNK_EVERY then
      lastChunk = now
      local n = nextAddN
      nextAddN = nextAddN + 1
      pendingAdds[n] = {at = now}
      NET.post(host, {t = "madd", n = n, items = table.remove(chunks, 1)}, "madd" .. n)
    end
    for n, p in pairs(pendingAdds) do
      if now - p.at >= ADD_WAIT then
        pendingAdds[n] = nil
        U.emit("music.addResult", false, "no-answer")
      end
    end
  end

  function MUSIC.tick()
    local now = U.now()
    if wantPause then
      if now - wantPause.since > PAUSE_GIVEUP then
        wantPause = nil
      elseif now >= wantPause.next then
        sendPause()
      end
    end
    if NET.isHost() then
      hostTick(now)
    elseif NET.inSession() then
      peerTick(now)
    end
    followTick(now)
  end

  -- Test hook: the host's internal flags.
  function MUSIC.debug()
    return {autoPaused = autoPaused, override = override, epoch = epoch, issued = issued, playTry = playTry,
      wantPause = wantPause}
  end

  wum.timers.every(0, U.guard("music", MUSIC.tick))
end

-- ==== src/50_layout.lua ====
-- layout (P2): where the player sits (design 2.3 and 2.4), the view (full, pill, hidden), the auto-hide gate while
-- this machine aims and fires, and the fades. It never draws and never claims regions; P3 draws from these rects.
-- Bus events: "layout.view" (view), "layout.anchor" (anchor), "layout.size" (w, h) once an animation settles.
do
  local ANIM, CTRL_FADE, FADE = 0.35, 0.25, 0.15     -- seconds
  local FADED = 0.3                                    -- alpha under a pause menu or the weapon panel
  local MARGIN, FRAME, PANEL_PAD, TAG, BAR = 24, 9, 12, 44, 64
  -- Pixels at 1080p between the top margin and the corner player, so the wind disc and the worm health badge under
  -- it stay visible. Measured from match screenshots (1920x1080 and 1280x720, the HUD scales with the height): the
  -- disc spans y 81..213 and the badge with its team bars y 270..365 at 1080p, so the frame starts at
  -- 24 + 347 = 371 and its picture at 380. The left corner uses the same offset, which also clears the radar (y 70..260).
  local WIND_OFFSET = 347
  local SETTLE_QUIET, FLIGHT_FAILSAFE = 0.6, 8         -- the flight gate (seconds)
  -- Only first-person aiming (Q held) means "aiming": WormAiming, Fire and UtilityFire are switched on for the whole of
  -- one's own turn whenever the worm holds a weapon (measured in game: Menu, InGame, WormAiming, WormMoving,
  -- CameraSelect, Fire, CrateChuteRelease while just standing), so they would hide the player for every turn.
  -- Third-person charging is covered by the fire-held gate and the shot by the flight gate.
  local AIM_GROUPS = {WormFirstPersonAiming = true}
  LAYOUT.WIND_OFFSET = WIND_OFFSET

  -- "hidden" lasts for the session only: a launch starts shown, so a party joined later is never silent and unseen.
  local lastShown = U.pref("lastShown", "full") == "pill" and "pill" or "full"
  local view = U.pref("view", "full")
  if view ~= "full" and view ~= "pill" then view = lastShown end
  local anchor = "corner"
  local cur, from, animT = nil, nil, nil     -- displayed rect {x0, y0, x1, y1}; animation start rect and time
  local winW, winH = 0, 0
  local alpha, alphaTarget, ctrlAlpha = 1, 1, 1
  local faded, autoHidden = false, false
  local sentW, sentH = nil, nil
  -- the auto-hide gate
  local fireDown, inFlight, flightAt, boomAt = false, false, 0, nil

  local function now() return U.now() / 1000 end

  function LAYOUT.view() return view end
  function LAYOUT.anchor() return anchor end
  function LAYOUT.alpha() return alpha end
  function LAYOUT.controlsAlpha() return ctrlAlpha * alpha end
  function LAYOUT.autoHidden() return autoHidden end
  function LAYOUT.faded() return faded end
  function LAYOUT.side() return CFG.get("panelSide") == "left" and "left" or "right" end
  function LAYOUT.animating() return animT ~= nil end

  -- Interactive means P3 may claim regions: shown, not faded, not auto-hidden, and fully faded in.
  function LAYOUT.interactive()
    return view ~= "hidden" and not autoHidden and not faded and alpha >= 0.95
  end

  local function baseScale(h) return U.clamp(h / 1080, 0.6, 2.5) end
  function LAYOUT.scale()
    local _, h = wum.render.windowSize()
    return baseScale(h) * CFG.get("uiScale") / 100
  end

  function LAYOUT.setView(v)
    if v ~= "full" and v ~= "pill" and v ~= "hidden" then return false end
    if v ~= "hidden" then
      lastShown = v
      U.setPref("lastShown", v)
    end
    if v == view then return true end
    view = v
    U.setPref("view", v)
    U.emit("layout.view", v)
    return true
  end

  -- The hide hotkey: full or pill <-> hidden (back to the last shown view).
  function LAYOUT.toggleHide()
    if view == "hidden" then return LAYOUT.setView(lastShown) end
    return LAYOUT.setView("hidden")
  end

  ---------------------------------------------------------------- rects

  -- The corner video rect for a window: 22 % of min(W, H*16/9) wide (times uiScale), 16:9, inside a 9 px frame
  -- with a 24 px margin, below the wind disc.
  function LAYOUT.cornerRect(W, H, side)
    local s0 = baseScale(H)
    local k = CFG.get("uiScale") / 100
    local s = s0 * k
    local vw = 0.22 * math.min(W, H * 16 / 9) * k
    local vh = vw * 9 / 16
    local y0 = MARGIN * s + WIND_OFFSET * s0 + FRAME * s
    local x0
    if side == "left" then x0 = MARGIN * s + FRAME * s else x0 = W - MARGIN * s - FRAME * s - vw end
    return x0, y0, x0 + vw, y0 + vh
  end

  -- The half panel: video, title tag above and control bar below, vertically centred in one half of the window.
  -- Returns the video rect and the panel rect (tag and bar included).
  function LAYOUT.halfRects(W, H, side)
    local s = baseScale(H) * CFG.get("uiScale") / 100
    local m, pad, tag, bar = MARGIN * s, PANEL_PAD * s, TAG * s, BAR * s
    local px0, px1
    if side == "left" then px0, px1 = m, W / 2 - m else px0, px1 = W / 2 + m, W - m end
    local vw = (px1 - px0) - 2 * pad
    local vh = vw * 9 / 16
    local room = H - 2 * m - tag - bar
    if vh > room then
      vh = math.max(room, 1)
      vw = vh * 16 / 9
      local cx = (px0 + px1) / 2
      px0, px1 = cx - vw / 2 - pad, cx + vw / 2 + pad
    end
    local total = tag + vh + bar
    local py0 = (H - total) / 2
    local vx0 = px0 + pad
    local vy0 = py0 + tag
    return {vx0, vy0, vx0 + vw, vy0 + vh}, {px0, py0, px1, py0 + total}
  end

  local function target()
    local side = LAYOUT.side()
    if anchor == "half" then
      local v = LAYOUT.halfRects(winW, winH, side)
      return v
    end
    return {LAYOUT.cornerRect(winW, winH, side)}
  end

  function LAYOUT.rect()
    local r = cur or target()
    return r[1], r[2], r[3], r[4]
  end

  function LAYOUT.panelRect()
    local _, p = LAYOUT.halfRects(winW, winH, LAYOUT.side())
    return p[1], p[2], p[3], p[4]
  end

  -- The minimised pill, at the top of the player's side.
  function LAYOUT.pillRect()
    local s = baseScale(winH) * CFG.get("uiScale") / 100
    local w, h = 300 * s, 56 * s
    local y0 = MARGIN * s + WIND_OFFSET * baseScale(winH)
    if LAYOUT.side() == "left" then return MARGIN * s, y0, MARGIN * s + w, y0 + h end
    return winW - MARGIN * s - w, y0, winW - MARGIN * s, y0 + h
  end

  -- What the decoder should render once the rect settled: 422x238 (corner) or 960x540 (half, at most 1280x720),
  -- scaled like the layout.
  function LAYOUT.sizeHint()
    local s = baseScale(winH > 0 and winH or 1080) * CFG.get("uiScale") / 100
    if anchor == "half" then
      local w = math.min(960 * s, 1280)
      return math.floor(w + 0.5), math.floor(w * 9 / 16 + 0.5)
    end
    return math.floor(422 * s + 0.5), math.floor(238 * s + 0.5)
  end

  ---------------------------------------------------------------- the rules

  local function inMatch()
    if wum.game.inMatch then
      local ok, v = pcall(wum.game.inMatch)
      if ok and v then return true end
    end
    return NET.phase() == "match"
  end

  local function onlineMatch()
    if not inMatch() then return false end
    return NET.inSession() or wum.game.online() == true
  end

  local function turnInfo()
    local ok, t = pcall(wum.game.turn)
    return ok and type(t) == "table" and t or nil
  end

  local function uiFlags()
    local ok, u = pcall(wum.game.ui)
    return ok and type(u) == "table" and u or {}
  end

  -- The anchor the table of design 2.4 gives now, or nil to keep the last one (between turns, the Ready? intro).
  function LAYOUT.ruleAnchor()
    if not onlineMatch() then return "corner" end
    local t, u = turnInfo(), uiFlags()
    if not t or u.readyIntro or t.team == nil then return nil end
    if t.mine then return "corner" end
    return CFG.get("bigOnOthers") and "half" or "corner"
  end

  local function myTurn(t)
    return inMatch() and t ~= nil and t.mine == true and t.team ~= nil
  end

  local function aiming()
    local ok, g = pcall(wum.input.groups)
    if not ok or type(g) ~= "table" then return false end
    for _, name in ipairs(g) do
      if AIM_GROUPS[name] then return true end
    end
    return false
  end

  local function resetFlight() inFlight, boomAt = false, nil end

  -- Auto-hide: my turn and (an aiming group is active, fire is held, or a shot is in flight). Audio is never muted
  -- by it (I3).
  function LAYOUT.gate()
    if not CFG.get("autoHideAim") then return false end
    local t = turnInfo()
    if not myTurn(t) then return false end
    local n = now()
    if inFlight then
      if (boomAt and n - boomAt >= SETTLE_QUIET) or n - flightAt >= FLIGHT_FAILSAFE then resetFlight() end
    end
    return fireDown or inFlight or aiming()
  end

  local function turnStarted()
    resetFlight()
    fireDown = false
  end

  wum.events.on("Input.FirePressed", U.guard("layout.fire", function() fireDown = true end))
  wum.events.on("Input.FireReleased", U.guard("layout.fire", function() fireDown = false end))
  wum.events.on("Weapon.Fired", U.guard("layout.fired", function()
    inFlight, flightAt, boomAt, fireDown = true, now(), nil, false
  end))
  wum.events.on("Explosion", U.guard("layout.boom", function()
    if inFlight then boomAt = now() end
  end))
  wum.events.on("Timer.StartRetreatTimer", U.guard("layout.retreat", resetFlight))
  wum.events.on("melange.turn", U.guard("layout.turn", turnStarted))
  wum.events.on("GameLogic.Turn.Started", U.guard("layout.turn", turnStarted))
  wum.events.on("melange.match.end", U.guard("layout.matchEnd", turnStarted))

  ---------------------------------------------------------------- update

  local function sameRect(a, b)
    return a and b and a[1] == b[1] and a[2] == b[2] and a[3] == b[3] and a[4] == b[4]
  end

  local function approach(v, goal, rate, dt)
    if v < goal then return math.min(goal, v + rate * dt) end
    return math.max(goal, v - rate * dt)
  end

  function LAYOUT.update(dt)
    dt = U.clamp(U.num(dt) or 0, 0, 0.25)
    local W, H = wum.render.windowSize()
    local resized = W ~= winW or H ~= winH
    winW, winH = W, H

    local want = LAYOUT.ruleAnchor() or anchor
    if want ~= anchor then
      from = cur and {cur[1], cur[2], cur[3], cur[4]} or nil
      anchor = want
      animT = from and 0 or nil
      ctrlAlpha = 0
      U.emit("layout.anchor", anchor)
    end
    local to = target()
    if resized or not cur then
      cur, animT, from = to, nil, nil
    elseif animT then
      animT = animT + dt
      local k = U.easeOutCubic(animT / ANIM)
      cur = {U.lerp(from[1], to[1], k), U.lerp(from[2], to[2], k), U.lerp(from[3], to[3], k),
        U.lerp(from[4], to[4], k)}
      if animT >= ANIM then cur, animT, from = to, nil, nil end
    elseif not sameRect(cur, to) then
      -- a setting changed the target (side, scale): animate there too
      from, animT, ctrlAlpha = cur, 0, 0
    end

    if not animT then
      ctrlAlpha = approach(ctrlAlpha, 1, 1 / CTRL_FADE, dt)
      local w, h = LAYOUT.sizeHint()
      if w ~= sentW or h ~= sentH then
        sentW, sentH = w, h
        U.emit("layout.size", w, h)
      end
    end

    local t, u = turnInfo(), uiFlags()
    faded = u.pause == true or (u.weaponPanel == true and myTurn(t))
    local gate = LAYOUT.gate()
    if gate and not autoHidden then
      autoHidden = true
    elseif not gate and autoHidden then
      autoHidden = false
    end
    if view == "hidden" or autoHidden then alphaTarget = 0
    elseif faded then alphaTarget = FADED
    else alphaTarget = 1 end
    alpha = approach(alpha, alphaTarget, 1 / FADE, dt)
  end

  LAYOUT.update(0)                  -- rects are valid before the first frame
  local last = U.now()
  wum.timers.every(0, U.guard("layout", function()
    local n = U.now()
    LAYOUT.update((n - last) / 1000)
    last = n
  end))
end

